/* DAWAH X — ahmad, অধ্যায় 44 · খণ্ড 44 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][44]=[[8601,8601,"","আমরা বাবার সব ভালোবাসা নিয়ে কথা বলেছি। আমি ঈশ্বরের কাছে প্রার্থনা করতে চাই। আল্লাহ যদি তার গলা ধরে রাখেন, তাহলে তিনি তার বই অথবা সে অবশ্যই তার বাবার কথা লিখেছে। তার বাসা আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمَّا خَلَقَ اللَّهُ عَزَّ وَجَلَّ خَلْقَهُ كَتَبَ غَلَبَتْ ‏ ‏أَوْ سَبَقَتْ ‏ ‏رَحْمَتِي غَضَبِي فَهُوَ عِنْدَهُ عَلَى الْعَرْشِ ‏","","",""],[8602,8602,"","আমরা যে মুক্ত বিষয় নিয়ে কথা বলেছি তা নিয়ে কথা বলেছি, আমি ঈশ্বরের কাছে প্রার্থনা করব, আর সে আমার কান্নায় ভরে দেবে, আমার মায়ের আবেগ.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ فَأُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي يَوْمَ الْقِيَامَةِ شَفَاعَةً لِأُمَّتِي ‏","","",""],[8603,8603,"","আমি বলতে চাচ্ছিলাম যে তার পশুগুলোর মধ্যে দিয়ে হয়তো সেরাটা হবে কিনা। যে আমার দুঃখকে আমি গ্রহণ করি, শেষটা হচ্ছে তুমি ভুল কিছু গান গাওয়া বন্ধ কর না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَقُولُ إِذَا ‏ ‏أَوَى ‏ ‏إِلَى فِرَاشِهِ اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ كُلِّ شَيْءٍ ‏ ‏فَالِقَ ‏ ‏الْحَبِّ وَالنَّوَى مُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْقُرْآنِ أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ ذِي شَرٍّ أَنْتَ آخِذٌ ‏ ‏بِنَاصِيَتِهِ ‏ ‏أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ اقْضِ عَنِّي الدَّيْنَ وَأَغْنِنِي مِنْ الْفَقْرِ ‏","","",""],[8604,8604,"","আমরা আমার বাবার সাথে আমার ভালবাসার কথা বলেছিলাম সে বলবে তুমি বলবে না যে, পরেরবার সে যখন ভালো কাজ করবে, তখন সে তাকে ঠিক করে দেবে, এটা ভালো হবে আমি বলতে চাচ্ছি সে যদি তার কথা কখনও শুনে, সে সম্ভবত তাকে মেরে ফেলবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَحَدَكُمْ ‏ ‏لَيَتَصَدَّقُ ‏ ‏بِالتَّمْرَةِ مِنْ الْكَسْبِ الطَّيِّبِ فَيَضَعُهَا فِي حَقِّهَا ‏ ‏فَيَلِيهَا ‏ ‏اللَّهُ بِيَمِينِهِ ثُمَّ مَا ‏ ‏يَبْرَحُ ‏ ‏فَيُرَبِّيهَا كَأَحْسَنِ مَا ‏ ‏يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏حَتَّى تَكُونَ مِثْلَ الْجَبَلِ أَوْ أَعْظَمَ مِنْ الْجَبَلِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏أَيْضًا ‏ ‏يَعْنِي ‏ ‏عَفَّانَ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏أَظُنُّهُ ‏ ‏الْوَاسِطِيَّ ‏ ‏بِإِسْنَادِهِ وَمَعْنَاهُ إِلَّا أَنَّهُ قَالَ فَيَقْبَلُهَا اللَّهُ عَزَّ وَجَلَّ بِيَمِينِهِ ‏","","",""],[8605,8605,"","আমরা আমাদের বাবার বাবার বাবার বাবার সাথে প্রত্নতায় বাপ্তিস্ম নিয়েছি। ঈশ্বর তাকে বলেছেন যখন তিনি সাহায্য করবেন, তিনি যখন চলে যাবেন, তখন তিনি তাকে বলবেন, আমি তাঁর উপর বিশ্বাস করি এবং পাই অনেক কিছু করে। \"আমি তাকে অনেক পছন্দ করি, সে তার হিংসায় লিপ্ত হয়, আমাকে শ্বশুর আব্বা হতে হবে, আর আমি বলবো \"পামো\" একটা স্বপ্ন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ رَاكِبٌ عَلَى بَقَرَةٍ الْتَفَتَتْ إِلَيْهِ فَقَالَتْ إِنِّي لَمْ أُخْلَقْ لِهَذَا إِنَّمَا خُلِقْتُ لِلْحِرَاثَةِ قَالَ فَآمَنْتُ بِهِ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏قَالَ وَأَخَذَ الذِّئْبُ شَاةً فَتَبِعَهَا الرَّاعِي فَقَالَ الذِّئْبُ مَنْ لَهَا يَوْمَ السَّبُعِ يَوْمَ لَا رَاعِيَ لَهَا غَيْرِي قَالَ فَآمَنْتُ بِهِ أَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏وَمَا هُمَا يَوْمَئِذٍ فِي الْقَوْمِ ‏","","",""],[8606,8606,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে তাকে এটা শুনতে সাহায্য করার আনন্দ নিয়ে। আমি তোমার ধ্বংস করে দেবো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8607,8607,"","বাবার আবেগ নিয়ে আমরা কথা বলেছি, বাবার স্বপ্নের কারণে আমরা আমার ছেলের অবতরনের স্বপ্নের দ্বারা নিশ্চিত হয়েছি। তার তিন-চার ফিটের হাতে, সে হচ্ছে সেই লোক যে লড়াই করছে, বাবা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ ‏ ‏فَلْيُفْرِغْ ‏ ‏عَلَى يَدَيْهِ مِنْ إِنَائِهِ ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏ ‏فَقَالَ ‏ ‏قَيْسٌ الْأَشْجَعِيُّ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَكَيْفَ إِذَا جَاءَ ‏ ‏مِهْرَاسُكُمْ ‏ ‏قَالَ ‏ ‏أَعُوذُ بِاللَّهِ مِنْ شَرِّكَ يَا ‏ ‏قَيْسُ ‏","","",""],[8608,8608,"","আমরা আবেগ নিয়ে কথা বলেছি যখন আমরা তার কথা শুনি, তার কথা শুনে আমি সাহায্য করতে চেষ্টা করেছি। লর্ড তার জন্য প্রার্থনা করেছে এবং আশ্বস্ত করেছে যে, সে এই কাজের জন্য অধিবাসীদের সাহায্য করেছে। হতাশ হয়ে পৌঁছাতে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8609,8609,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের আরো ভাল করে বলতে বাধ্য করেছে যে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন। যদি আমরা প্রার্থনা করতে চাই, তুমি এগিয়ে যাও এবং চলে যাও। আমরা একটা কথা বলেছি। আমরা যদি বলি, আমরা একটা কথা বলি। আমরা যদি বলি, আমরা যদি বলি, আমরা এটা সত্যিই বলি, আমরা যদি বলি, আমরা সত্যিই আমাদের কাছে একটা জিনিস আছে। কিন্তু আমরা যদি আমাদের কাছে এটা একটা জিনিস আছে। এবং আমরা শুধু একটা জিনিস নিয়ে যাই। আমরা যদি বলি, আমরা শুধু একটা প্রশ্ন করি, আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা যদি চাই, আমরা যদি চাই, আমরা শুধু একটা কথা বলি, তাহলে আমরা শুধু একটা কথা বলি। কিন্তু আমরা শুধু একটা কথা বলি, আমরা শুধু একটা সুন্দর জিনিস, আর কি করি। কিন্তু আমরা যদি এটা আমাদের কাছের জন্য। আমরা শুধু একটা প্রশ্ন করি, তাহলে আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা যদি আমরা শুধু একটা প্রশ্ন করি, তাহলে আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা শুধু একটা প্রশ্ন করি। কিন্তু আমরা যদি আমরা শুধু একটা প্রশ্ন করি, আমরা কি করবো। কিন্তু আমরা কি করবো। কিন্তু আমরা কি করবো? আমার বাবার প্রতি ভালোবাসা, ঈশ্বরের দেবী, আপনার মত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ فَلَا تَأْتُوهَا ‏ ‏تَسْعَوْنَ ‏ ‏وَلَكِنْ امْشُوا مَشْيًا عَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا سَبَقَكُمْ فَاقْضُوا ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[8610,8610,"","আমার বাবার দোহাই ঘোড়া হাতে ধরে আমি কথা বলেছি। ঈশ্বরের কাছে আছে এবং আমরা আত্মসমর্পন করব এবং আমি কাপুরুষ হয়ে যাব, এমনকি আমি মারা যাওয়ার পরেও। আমি শুধু বলেছিলাম, আমি শুধু বলতে চাই, আমার বাবার উপর ঘোড়া হাতে ধরে। আমরা শিয়াল ছিলাম, বেঁচে আছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَقِيتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَمَشَيْتُ مَعَهُ حَتَّى قَعَدَ فَانْسَلَلْتُ فَأَتَيْتُ ‏ ‏الرَّحْلَ ‏ ‏فَاغْتَسَلْتُ ثُمَّ جِئْتُ وَهُوَ قَاعِدٌ فَقَالَ أَيْنَ كُنْتَ فَقُلْتُ لَقِيتَنِي وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَكَرِهْتُ أَنْ أَجْلِسَ إِلَيْكَ وَأَنَا ‏ ‏جُنُبٌ ‏ ‏فَانْطَلَقْتُ فَاغْتَسَلْتُ قَالَ سُبْحَانَ اللَّهِ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يَنْجُسُ ‏","","",""],[8611,8611,"","আমরা আমাদের ভালবাসার একটা খেলনার জন্য একটা বিড়ালের কাছে নিয়ে এসেছি, সে ঈশ্বরের কাছে প্রার্থনা করার জন্য প্রার্থনা করেছিল, সে পানি উৎপাদন শেষ করে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ جُحَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كَسْبِ ‏ ‏الْإِمَاءِ ‏","","",""],[8612,8612,"","আমরা আমার বাবাকে রাজা হওয়ার ব্যাপারে কথা বলেছিলাম আর আমি হয়তো শুনতে পাই ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏وَلَا ‏ ‏أُرَانِي إِلَّا قَدْ ‏ ‏سَمِعْتُهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[8613,8613,"","আমরা যাজকের সাথে আমার বাবার কথা বলেছিলাম, প্রাপ্তবয়স্ক, যে কিনা এর সাথে যেতে চাচ্ছে, ঈশ্বর প্রার্থনা করেছেন আর পর্বত আর ভালোর কথা বলেছেন। সেরাটা।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ يَعْنِي الرَّازِيَّ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمْسُ ‏","","",""],[8614,8614,"","তিনি বলেছিলেন, তিনি আপনার আনুগত্যের জন্য সমবেদনা বোধ করেছিলেন কিন্তু তারা অনেক ভদ্র হতো । তারা যা করতে পারে তা হল, তারা যা করতে পারে তা হল, আমি ঈশ্বরের সমবেদনা কামনা করছি এবং এটা জানা যে কে আপনার কাছে এসেছে। তারা আপনাকে রক্ষা করবে এবং তারা আপনাকে বলবে এবং যদি তারা তা করে। তারা আমার ভ্রূণ দেখে বলেছে তারা আপনাকে কোন জিনিষ দেবে না... ...তারা বলবে তুমি কে, নাকি তারা তোমাকে দেখবে. যখন সে বাইরে যাচ্ছিল, সে তাদের সাথে বসে বলছিল যে তারা হয়তো হারিয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلَّهِ عَزَّ وَجَلَّ مَلَائِكَةً ‏ ‏سَيَّارَةً ‏ ‏فُضُلًا ‏ ‏يَبْتَغُونَ مَجَالِسَ الذِّكْرِ وَإِذَا وَجَدُوا مَجْلِسًا فِيهِ ذِكْرٌ قَعَدُوا مَعَهُمْ فَحَضَنَ بَعْضُهُمْ بَعْضًا بِأَجْنِحَتِهِمْ حَتَّى يَمْلَئُوا مَا بَيْنَهُمْ وَبَيْنَ سَمَاءِ الدُّنْيَا فَإِذَا تَفَرَّقُوا ‏ ‏عَرَجُوا ‏ ‏أَوْ صَعِدُوا ‏ ‏إِلَى السَّمَاءِ قَالَ فَيَسْأَلُهُمْ اللَّهُ عَزَّ وَجَلَّ وَهُوَ أَعْلَمُ مِنْ أَيْنَ جِئْتُمْ فَيَقُولُونَ جِئْنَاكَ مِنْ عِنْدِ عِبَادٍ لَكَ فِي الْأَرْضِ يُسَبِّحُونَكَ وَيُكَبِّرُونَكَ وَيَحْمَدُونَكَ وَيُهَلِّلُونَكَ وَيَسْأَلُونَكَ قَالَ وَمَاذَا يَسْأَلُونِي قَالُوا يَسْأَلُونَكَ جَنَّتَكَ قَالَ وَهَلْ رَأَوْا جَنَّتِي قَالُوا لَا أَيْ رَبِّ قَالَ فَكَيْفَ لَوْ قَدْ رَأَوْا جَنَّتِي قَالُوا وَيَسْتَجِيرُونَكَ قَالَ مِمَّ يَسْتَجِيرُونِي قَالُوا مِنْ نَارِكَ يَا رَبِّ قَالَ ‏ ‏وَهَلْ رَأَوْا نَارِي قَالُوا لَا قَالُوا وَيَسْتَغْفِرُونَكَ قَالَ فَيَقُولُ قَدْ غَفَرْتُ لَهُمْ وَأَعْطَيْتُهُمْ مَا سَأَلُوا ‏ ‏وَأَجَرْتُهُمْ ‏ ‏مِمَّا ‏ ‏اسْتَجَارُوا ‏ ‏قَالَ فَيَقُولُونَ رَبِّ فِيهِمْ فُلَانٌ عَبْدٌ خَطَّاءٌ إِنَّمَا مَرَّ فَجَلَسَ مَعَهُمْ قَالَ فَيَقُولُ قَدْ غَفَرْتُ لَهُمْ هُمْ الْقَوْمُ لَا يَشْقَى بِهِمْ جَلِيسُهُمْ ‏","","",""],[8615,8615,"","আমরা ব্যাপ্টিস্ট মসজিদ সম্পর্কে কথা বলেছি, আমার ভালবাসার ঈর্ষা একটা পরীর স্বপ্ন, আমি তাকে চিনি না, ছেলেটি তার কাছে প্রার্থনা করে। সে বলবে, সে তার দেখা দেখেছে। ( আদিপুস্তক ১: ২৭) কিন্তু, তিনি খুশি হতেন যে, তার এমন একজন পুত্র ছিল, যিনি একটা ছেলে ছিলেন, যিনি ঈশ্বরের কাছে যান এমন একজন পুত্র ছিলেন, যিনি একটা ছেলে ছিলেন । আমি যা চুরি করেছি তা হল আমি ঈশ্বরে বিশ্বাস করি এবং আমার দৃষ্টিকে মিথ্যা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَغَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَى ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏رَجُلًا يَسْرِقُ فَقَالَ لَهُ يَا فُلَانُ أَسَرَقْتَ قَالَ لَا وَاللَّهِ مَا سَرَقْتُ قَالَ آمَنْتُ بِاللَّهِ وَكَذَّبْتُ بَصَرِي ‏","","",""],[8616,8616,"","বাবা খুশি যে তার জন্য ঈশ্বরের কাছে প্রার্থনা করছে আর তারপর তাকে আত্মসমর্পণ করতে হবে। তার উত্তর শুনে আমার বাবা সাঁতার কেটে বলেন, চুরি করা এবং এই অনুভূতি থেকে তাকে শুনতে পান।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ أَبِي مُسْلِمٍ ‏ ‏قَالَ أَشْهَدُ عَلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَأَبِي سَعِيدٍ ‏ ‏أَنَّهُمَا ‏ ‏شَهِدَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ اللَّهَ يُمْهِلُ حَتَّى يَذْهَبَ ثُلُثُ اللَّيْلِ ثُمَّ يَهْبِطُ فَيَقُولُ هَلْ مِنْ دَاعٍ فَيُسْتَجَابُ لَهُ هَلْ مِنْ مُسْتَغْفِرٍ فَيُغْفَرُ لَهُ ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏وَكَانَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا بِأَحَادِيثَ عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏ثُمَّ بَلَغَنِي بَعْدُ أَنَّهُ قَالَ سَمِعْتُهَا مِنْ ‏ ‏إِسْرَائِيلَ ‏ ‏وَأَحْسَبُ هَذَا الْحَدِيثَ فِيهَا ‏","","",""],[8617,8617,"","আমরা কথা বলেছিলাম, আমার হৃদয়ের ক্যান্সারের সাথে বাবার পাশ দিয়ে যেতে হয় আর বলে যে সে ঈশ্বরের কথা শোনে, কেটে দাও, তুমি খুব খুশি হবে তোমাকে কে ধরে নিয়ে আমি তোমাকে কেটে ফেলবো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الْجَبَّارِ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏الرَّحِمَ ‏ ‏شُجْنَةٌ ‏ ‏مِنْ الرَّحْمَنِ تَقُولُ يَا رَبِّ إِنِّي قُطِعْتُ يَا رَبِّ إِنِّي أُسِيءَ إِلَيَّ يَا رَبِّ إِنِّي ظُلِمْتُ يَا رَبِّ يَا رَبِّ قَالَ فَيُجِيبُهَا أَمَا تَرْضَيْنَ أَنْ أَصِلَ مَنْ وَصَلَكِ وَأَقْطَعَ مَنْ قَطَعَكِ ‏","","",""],[8618,8618,"","আমরা কথা বলেছিলাম আমার বাবা ভালোবাসা মুক্ত হয়ে থাকলে কথা বলতে, সে বলতো যদি আমি তোমাকে সূর্যের মধ্যে পেতাম, সে এটা কেটে ফেলত।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ جَالِسًا فِي الشَّمْسِ فَقَلَصَتْ عَنْهُ فَلْيَتَحَوَّلْ مِنْ مَجْلِسِهِ ‏","","",""],[8619,8619,"","আমাদের কথাবার্তার ব্যাপারে আমরা কথা বলেছি আর এটা আমার বাবার নগ্ন হওয়ার ব্যাপারে। ঈশ্বর বলেছেন তিনি তার ক্ষমতা দেবেন না। দুটো ঘোড়া ছিল, আর তার সেটা দেখতে হতো, যাতে ঈশ্বর সেটা শাসন করতে পারেন। তারপর সে দেখতে পাবে তার রাস্তা নাকি সকালে অথবা আগুনের পাশে। তার চিন্তা, তার যা করার ছিল তা হল, সে কি করেছে। তার দাসেরা পাঁচ বছর আগে তার কাছে এসেছিল, তার প্রতিজ্ঞা অনুযায়ী তিনি তার দায়িত্ব পালন করবেন না, যেমনটা তিনি কেবল তার কর্তব্য পালন করেন সে তার যথাসাধ্য চেষ্টা করেছে, আমি এক বছর তোমার প্রতিশ্রুতি পালন করব আর তারপর দেখতে পারব তার উপায় কি হবে অথবা তার গতি খারাপ হবে। তার শেষ মৃত্যু হবে তিন বছরের এক বৃদ্ধের মৃত্যুর... ...যে প্রতিবেশী, আমার কাছে তার ভাড়া আছে, আর সে তাকে ঈশ্বরের পথে নিয়ে যায়, তাই সে ভালো আছে। তার পরিকল্পনা ছিল, ভাড়া করা, তার কাছ থেকে প্রাণ ভাগ করে নেওয়া আর তার কাছ থেকে ভাগ করে নেওয়া, আমি তার আসবাবপত্র আর তার বাবা-মাদের সাথে দৌড়াচ্ছি, তার স্বপ্ন তার বিছানায় আছে, আর তার গোপনীয়তা চলে গেছে, আর একটা ফুল নিয়ে গেছে। তিনি বলেছেন, \"আমি আছি।\" একটা ভাল জিনিস দেখে মনে হচ্ছে যে এটা দেখে আর এর থেকে তৃতীয়বারও ভাল। আমার বাবা এটা দিয়েছেন ঈশ্বরের একজন কুমারী আর আমরা সবাই এখন আত্মসমর্পণ করছি। আমরা আমার বাবার সাথে এমন একটা নিয়ম নিয়ে কথা বলেছি, যা আগামীকালের বয়সের কথা বলেছিল যে এটা ঘটেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبُ بْنُ خَالِدٍ الْبَصْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ صَاحِبِ ‏ ‏كَنْزٍ ‏ ‏لَا يُؤَدِّي زَكَاتَهُ إِلَّا جِيءَ بِهِ يَوْمَ الْقِيَامَةِ ‏ ‏وَبِكَنْزِهِ ‏ ‏فَيُحْمَى عَلَيْهِ صَفَائِحُ فِي نَارِ جَهَنَّمَ ‏ ‏فَيُكْوَى بِهَا جَبِينُهُ وَجَنْبُهُ وَظَهْرُهُ حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ إِبِلٍ لَا ‏ ‏يُؤَدِّي زَكَاتَهَا إِلَّا جِيءَ بِهِ يَوْمَ الْقِيَامَةِ وَبِإِبِلِهِ ‏ ‏كَأَوْفَرِ ‏ ‏مَا كَانَتْ عَلَيْهِ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏كُلَّمَا مَضَى أُخْرَاهَا ‏ ‏رُدَّ ‏ ‏عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ وَمَا مِنْ صَاحِبِ غَنَمٍ لَا يُؤَدِّي زَكَاتَهَا إِلَّا جِيءَ بِهِ وَبِغَنَمِهِ يَوْمَ الْقِيَامَةِ ‏ ‏كَأَوْفَرِ ‏ ‏مَا كَانَتْ ‏ ‏فَيُبْطَحُ ‏ ‏لَهَا ‏ ‏بِقَاعٍ ‏ ‏قَرْقَرٍ ‏ ‏فَتَطَؤُهُ ‏ ‏بِأَظْلَافِهَا ‏ ‏وَتَنْطَحُهُ بِقُرُونِهَا كُلَّمَا مَضَتْ أُخْرَاهَا رُدَّتْ عَلَيْهِ أُولَاهَا حَتَّى يَحْكُمَ اللَّهُ بَيْنَ عِبَادِهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ ثُمَّ يُرَى سَبِيلَهُ إِمَّا إِلَى الْجَنَّةِ وَإِمَّا إِلَى النَّارِ قِيلَ يَا رَسُولَ اللَّهِ فَالْخَيْلُ قَالَ الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ وَالْخَيْلُ ثَلَاثَةٌ وَهِيَ لِرَجُلٍ أَجْرٌ وَهِيَ لِرَجُلٍ سِتْرٌ وَهِيَ عَلَى رَجُلٍ ‏ ‏وِزْرٌ ‏ ‏فَأَمَّا الَّذِي هِيَ لَهُ أَجْرٌ الَّذِي يَتَّخِذُهَا وَيَحْبِسُهَا فِي سَبِيلِ اللَّهِ فَمَا غَيَّبَتْ فِي بُطُونِهَا فَهُوَ لَهُ أَجْرٌ وَإِنْ ‏ ‏اسْتَنَّتْ ‏ ‏مِنْهُ ‏ ‏شَرَفًا ‏ ‏أَوْ ‏ ‏شَرَفَيْنِ ‏ ‏كَانَ لَهُ فِي كُلِّ خُطْوَةٍ خَطَاهَا أَجْرٌ وَلَوْ ‏ ‏عَرَضَ ‏ ‏لَهُ نَهْرٌ فَسَقَاهَا مِنْهُ كَانَ لَهُ بِكُلِّ قَطْرَةٍ غَيَّبَتْهُ فِي بُطُونِهَا أَجْرٌ حَتَّى ذَكَرَ الْأَجْرَ فِي ‏ ‏أَرْوَاثِهَا ‏ ‏وَأَبْوَالِهَا وَأَمَّا الَّذِي هِيَ لَهُ سِتْرٌ فَرَجُلٌ يَتَّخِذُهَا تَعَفُّفًا ‏ ‏وَتَجَمُّلًا ‏ ‏وَتَكَرُّمًا وَلَا ‏ ‏يَنْسَى حَقَّهَا فِي ظُهُورِهَا وَبُطُونِهَا فِي عُسْرِهَا وَيُسْرِهَا وَأَمَّا الَّذِي هِيَ عَلَيْهِ ‏ ‏وِزْرٌ ‏ ‏فَرَجُلٌ يَتَّخِذُهَا ‏ ‏أَشَرًا ‏ ‏وَبَطَرًا ‏ ‏وَرِئَاءَ ‏ ‏النَّاسِ ‏ ‏وَبَذَخًا ‏ ‏عَلَيْهِ قِيلَ يَا رَسُولَ اللَّهِ فَالْحُمُرُ قَالَ مَا أُنْزِلَ عَلَيَّ فِيهَا شَيْءٌ إِلَّا هَذِهِ الْآيَةُ الْجَامِعَةُ ‏ ‏الْفَاذَّةُ ‏ { ‏فَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ شَرًّا يَرَهُ ‏} ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَ هَذَا الْكَلَامِ كُلِّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَبُو عُمَرَ الْغُدَانِيُّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏بِهَذَا الْحَدِيثِ ‏","","",""],[8620,8620,"","আমি একজনকে মারার চেষ্টা করার একদিন পর আমরা এক দিন সম্বন্ধে কথা বলেছিলাম । ( গীতসংহিতা ৩৭: ১১) ঈশ্বর ও তাঁর পুত্র সম্বন্ধে জ্ঞান নেওয়ার জন্য তিনি কোন ব্যবস্থা করেছিলেন?","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ يَعْنِي ابْنَ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ وَاسْمُهُ هَرِمُ بْنُ عَمْرِو بْنِ جَرِيرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَدَبَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا جِهَادٌ فِي سَبِيلِ اللَّهِ وَإِيمَانًا بِي وَتَصْدِيقًا بِرُسُلِي أَنَّهُ عَلَيَّ ضَامِنٌ أَنْ أُدْخِلَهُ الْجَنَّةَ أَوْ أُرْجِعَهُ إِلَى مَسْكَنِهِ الَّذِي خَرَجَ مِنْهُ ‏ ‏نَائِلًا ‏ ‏مَا ‏ ‏نَالَ ‏ ‏مِنْ أَجْرٍ أَوْ ‏ ‏غَنِيمَةٍ ‏","","",""],[8621,8621,"","সে বলল ভগবান তার জন্য প্রার্থনা করছে আর সে প্রভুর অনুগ্রহে যা কিছু করেছে তা আত্মসমর্পণ করবে।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ ‏ ‏مَكْلُومٍ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِ اللَّهِ إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ كَهَيْئَتِهِ يَوْمَ ‏ ‏كُلِمَ ‏ ‏وَكَلْمُهُ ‏ ‏يَدْمَى اللَّوْنُ لَوْنُ دَمٍ وَالرِّيحُ رِيحُ مِسْكٍ ‏","","",""],[8622,8622,"","আর তিনি বলেছিলেন যে ঈশ্বর তাকে প্রার্থনা করেছেন যেন তিনি তার হাতে আমার আত্মা সমর্পণ করেন অথবা যাকে আমি তার হাত থেকে আত্মসমর্পণ করি তার কাছে আমি আত্মসমর্পণ করি বা যার কাছে আমি জীবিত থাকি। সার্ভিস, তুমি ভালো লর্ড, কিন্তু আমি কি করতে পারি তা আমি খুঁজে পাচ্ছি না, আমার শত্রুকে জয় করতে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي مَا قَعَدْتُ خِلَافَ ‏ ‏سَرِيَّةٍ ‏ ‏تَغْدُو ‏ ‏فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ وَلَكِنْ لَا أَجِدُ مَا ‏ ‏أَحْمِلُهُمْ ‏ ‏وَلَا يَجِدُونَ سَعَةً فَيَتْبَعُونِي وَلَا تَطِيبُ أَنْفُسُهُمْ أَنْ يَتَخَلَّفُوا بَعْدِي ‏","","",""],[8623,8623,"","আমি যখন তাকে বলেছিলাম যে, আমি যদি তার কাছে ফিরে যাই, তা হলে সে আমার সবচেয়ে ভালোটা দিয়ে দেবে ।","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَوَدِدْتُ أَنْ أَغْزُوَ فِي سَبِيلِ اللَّهِ فَأُقْتَلَ ثُمَّ أَغْزُوَ فَأُقْتَلَ ثُمَّ أَغْزُوَ فَأُقْتَلَ ‏","","",""],[8624,8624,"","আমরা একটা বাপ্তিস্মের কথা বলেছি যা আমাদের বলেছে যে বেন সিরের খুশি হবে, ঈশ্বর এটা উদ্ধার করতে হবে আর আমি এই পর্দার সব আবরণের জিনিয়াসের আদেশ দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ بِقَرْيَةٍ تَأْكُلُ ‏ ‏الْقُرَى ‏ ‏وَتَنْفِي ‏ ‏الْخَبَثَ ‏ ‏كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ ‏ ‏الْحَدِيدِ ‏","","",""],[8625,8625,"","আমি আমার বাবার প্রতি করুণা দেখানোর ব্যাপারে কথা বলেছি, কিন্তু আমরা আমার বাবার নগ্ন হওয়ার ব্যাপারে কথা বলেছি। ঈশ্বর বলে দিয়েছেন, তোমার ভাইয়ের সাথে আমি যা বলি, ঈশ্বর তাই বলছেন। ভাই, আপনি হয়তো মিস করেছেন এবং যদি আপনি না বলেন,","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ مَا ‏ ‏الْغِيبَةُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قَالَ أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ أَيْ رَسُولَ اللَّهِ قَالَ إِنْ كَانَ فِي أَخِيكَ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[8626,8626,"","আমি ঈশ্বরের কাছে শপথ করে বলছি যে, আমি একজন বিজয়ী এবং খাবার এবং অন্যান্য জিনিস দিয়ে দেই। আর কেউ ক্ষমা করবে, যদি তুমি আমাকে জিজ্ঞেস কর যে, এটা আমার বাবার একজন পলাতক, সে বলবে সকালে সকাল সকালটা যেন মাসের মতো দিনের দিন, যেদিন দিনের দিন, সেদিন যেদিন, সেই দিন, যেদিন যেদিন, সেই দিন, সেই দিন, যেদিন, সেই দিন, সেই দিন, যেদিন, সেই দিন, সেই দিন, যেদিন, সেই দিন, সেই দিন, যেদিন, সেই দিন, যেদিন, সেই দিন, সেই দিন, সেই দিন, যেদিন, সেই দিন, সেই দিন, দিনব্যাপী দিন, দিনব্যাপী এক দিন, দিনব্যাপী বিনিময়, এবং ‘ গণনা ’ অর্থাৎ, “দিবস ” অর্থাৎ ‘আধুনিক দিবস ’ অর্থাৎ“ সাকাতীত দিন । ” ( প্রকা) ধার্য করা হবে । দিনের দিন, যেদিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, দিন, সেদিন, আল্লাহ্‌র অনুগ্রহ ও শোকের নকশা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ فِي سَفَرٍ فَلَمَّا نَزَلُوا أَرْسَلُوا إِلَيْهِ وَهُوَ ‏ ‏يُصَلِّي لِيَطْعَمَ فَقَالَ لِلرُّسُلِ إِنِّي صَائِمٌ فَلَمَّا وُضِعَ الطَّعَامُ وَكَادُوا يَفْرُغُونَ جَاءَ فَجَعَلَ يَأْكُلُ فَنَظَرَ الْقَوْمُ إِلَى رَسُولِهِمْ فَقَالَ مَا تَنْظُرُونَ قَدْ أَخْبَرَنِي أَنَّهُ صَائِمٌ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏صَدَقَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَوْمُ شَهْرِ الصَّبْرِ وَثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ صَوْمُ الدَّهْرِ فَقَدْ صُمْتُ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَأَنَا مُفْطِرٌ فِي تَخْفِيفِ اللَّهِ وَصَائِمٌ فِي تَضْعِيفِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8627,8627,"","আমি আমার বাবার বাপ্তিস্মের কথা বলেছিলাম আমার ভালোবাসা নিয়ে একজন স্বাধীন মানুষ। ঈশ্বর তাকে আদেশ দিয়েছেন আর নিজেকে ঈশ্বরের উপর ভরসা রাখার আদেশ দিয়েছেন। আমার ছেলে ঈশ্বরের কাছে এক উত্তম জায়গা ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِ ‏ ‏لُوطٍ ‏ { ‏لَوْ أَنَّ لِي بِكُمْ قُوَّةً أَوْ آوِي إِلَى رُكْنٍ شَدِيدٍ ‏} ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ إِلَى رَبِّهِ عَزَّ وَجَلَّ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا بُعِثَ بَعْدَهُ نَبِيٌّ إِلَّا فِي ثَرْوَةٍ مِنْ قَوْمِهِ ‏","","",""],[8628,8628,"","আমি আমার বাবার বাপ্তিস্মের কথা বলেছিলাম আমার ভালোবাসা মুক্ত হওয়ার ব্যাপারে। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং তিনি তাকে দেখা করতে হবে এবং সে তাকে ঘৃণা করে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ رَضِيَتْ فَلَهَا رِضَاهَا وَإِنْ كَرِهَتْ فَلَا جَوَازَ عَلَيْهَا ‏ ‏يَعْنِي الْيَتِيمَةَ ‏","","",""],[8629,8629,"","আমরা শিকারীদের হাত থেকে রক্ষা করার চেষ্টা করার কথা বলেছিলাম। আমার বাবা, যিনি তাকে আদেশ দিয়েছেন এবং তার প্রভুর কাছে তার প্রভুর মাধ্যমে উদ্ধার করবেন। ( যিশা.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيُّ بْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ يَمُوتُ يَشْهَدُ لَهُ ثَلَاثَةُ أَبْيَاتٍ مِنْ جِيرَانِهِ ‏ ‏الْأَدْنَيْنَ ‏ ‏بِخَيْرٍ إِلَّا قَالَ اللَّهُ عَزَّ وَجَلَّ قَدْ قَبِلْتُ شَهَادَةَ عِبَادِي عَلَى مَا عَلِمُوا وَغَفَرْتُ لَهُ مَا أَعْلَمُ ‏","","",""],[8630,8630,"","বাবার সাথে কথা বলে আমি কথা বলেছিলাম। সে আমাকে বলতে চাই। সে পতাকার টাকা দেবে এমন একজনকে, যে ঈশ্বরকে ভালোবাসে এবং ঈশ্বরের কাছে পাঠানো উচিত। আমি তার সাথে যুদ্ধ করতে চাই। আমি আগে কখনো চেষ্টা করেছি। তার উপর ভর করে, সিঁড়ি তাকে মেরে ফেলবে... ...আর সে তোমার মন নষ্ট করতে পারবে না। রক্ত তাদের নিজেদেরই জন্য, তারা ঠিক না আর তারা ঈশ্বরের দোহাইর জন্য দায়ী।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏لَأَدْفَعَنَّ ‏ ‏الرَّايَةَ ‏ ‏إِلَى رَجُلٍ يُحِبُّ اللَّهَ وَرَسُولَهُ يَفْتَحُ اللَّهُ عَلَيْهِ قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏فَمَا أَحْبَبْتُ ‏ ‏الْإِمَارَةَ ‏ ‏قَبْلَ يَوْمَئِذٍ فَتَطَاوَلْتُ لَهَا ‏ ‏وَاسْتَشْرَفْتُ ‏ ‏رَجَاءَ أَنْ يَدْفَعَهَا إِلَيَّ فَلَمَّا كَانَ الْغَدُ دَعَا ‏ ‏عَلِيًّا ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَدَفَعَهَا إِلَيْهِ فَقَالَ قَاتِلْ وَلَا تَلْتَفِتْ حَتَّى يُفْتَحَ عَلَيْكَ فَسَارَ قَرِيبًا ثُمَّ نَادَى يَا رَسُولَ اللَّهِ ‏ ‏عَلَامَ أُقَاتِلُ قَالَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا فَعَلُوا ذَلِكَ فَقَدْ مَنَعُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا وَحِسَابُهُمْ ‏ ‏عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8631,8631,"","আমার প্রিয় বিদায়ের কথা বলে আমি আমার বাবার সাথে কথা বলেছি। ঈশ্বর তাঁর সম্মান জানিয়ে বলেছেন, তাঁর সম্মানের জন্য। অপরাধটা হলো নরকের গেটের গেটে আটকে আছে এবং বেশীরভাগ ব্যবহার করা হয়। আমরা কথা বলেছি আর এর উত্তর দিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَشِّرُ أَصْحَابَهُ قَدْ ‏ ‏جَاءَكُمْ شَهْرُ رَمَضَانَ شَهْرٌ مُبَارَكٌ افْتَرَضَ اللَّهُ عَلَيْكُمْ صِيَامَهُ يُفْتَحُ فِيهِ أَبْوَابُ الْجَنَّةِ وَيُغْلَقُ فِيهِ أَبْوَابُ الْجَحِيمِ ‏ ‏وَتُغَلُّ ‏ ‏فِيهِ الشَّيَاطِينُ فِيهِ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ مَنْ حُرِمَ خَيْرَهَا فَقَدْ حُرِمَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏","","",""],[8632,8632,"","আমরা বাবার ব্যাপারে কথা বলেছি আমার বাবার বিরুদ্ধে দেবীর বিচার নিয়ে। ভগবানের কাছে আছে আর বলেছে সে ছায়াতে নেই, নাকি জীবাশ্ম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏سَبَقَ ‏ ‏إِلَّا فِي ‏ ‏خُفٍّ ‏ ‏أَوْ ‏ ‏حَافِرٍ ‏","","",""],[8633,8633,"","আমি আমার বাবার সাথে আমার ভাইকে ঈশ্বরের কাছে পাঠানো নিয়ে কথা বলেছিলাম। সে বলেছে যে, আমার ছেলে আমাকে খুন করবে যে একজন সার্জন ছিল। আমি তাকে বলেছিলাম যে তোমার মা তার প্রার্থনা শুনে আমাকে সম্মান করবে আর তারপর একবার বলেছিলেন যে কোন সার্জন আমার ছেলেকে চেনেন কিনা তা জানার জন্য। সে বলল, যতক্ষণ না পর্যন্ত লর্ড তাকে দোষ দেওয়া না পর্যন্ত মরে যায়... ...আর সে একজন প্রচারক যে তার গান গাইবে, সেই ছিল সেই লোক যে নিহত হয়েছিল। তারা আমার প্রার্থনাকে মেনে নিয়েছিল এবং আমার প্রার্থনা অনুসরণ করেছিল । আমি ভয় পেয়েছিলাম তারা বলেছে যে আমাদের নেকড়ে আর অন্যদের কাছ থেকে শোনা উচিৎ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَنْبَأَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ فِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏رَجُلٌ يُقَالُ لَهُ ‏ ‏جُرَيْجٌ ‏ ‏كَانَ يَتَعَبَّدُ فِي ‏ ‏صَوْمَعَتِهِ ‏ ‏فَأَتَتْهُ أُمُّهُ ذَاتَ يَوْمٍ فَنَادَتْهُ فَقَالَتْ أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ بُنَيَّ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ أُكَلِّمْكَ أَنَا أُمُّكَ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ قَالَ أَيْ رَبِّ صَلَاتِي وَأُمِّي فَأَقْبَلَ عَلَى صَلَاتِهِ ثُمَّ عَادَتْ فَنَادَتْهُ مِرَارًا فَقَالَتْ أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ بُنَيَّ ‏ ‏أَشْرِفْ ‏ ‏عَلَيَّ فَقَالَ أَيْ رَبِّ صَلَاتِي وَأُمِّي فَأَقْبَلَ عَلَى صَلَاتِهِ فَقَالَتْ اللَّهُمَّ لَا تُمِتْهُ حَتَّى تُرِيَهُ ‏ ‏الْمُومِسَةَ ‏ ‏وَكَانَتْ رَاعِيَةً ‏ ‏تَرْعَى غَنَمًا لِأَهْلِهَا ثُمَّ تَأْوِي إِلَى ظِلِّ ‏ ‏صَوْمَعَتِهِ ‏ ‏فَأَصَابَتْ فَاحِشَةً فَأُخِذَتْ فَحَمَلَتْ وَكَانَ مَنْ زَنَى مِنْهُمْ قُتِلَ قَالُوا مِمَّنْ قَالَتْ مِنْ ‏ ‏جُرَيْجٍ ‏ ‏صَاحِبِ ‏ ‏الصَّوْمَعَةِ ‏ ‏فَجَاءُوا بِالْفُؤُوسِ وَالْمُرُورِ فَقَالُوا أَيْ ‏ ‏جُرَيْجُ ‏ ‏أَيْ ‏ ‏مُرَاءٍ ‏ ‏ثُمَّ قَالُوا انْزِلْ فَأَبَى وَأَقْبَلَ عَلَى صَلَاتِهِ ‏ ‏يُصَلِّي فَأَخَذُوا فِي هَدْمِ ‏ ‏صَوْمَعَتِهِ ‏ ‏فَلَمَّا رَأَى ذَلِكَ نَزَلَ فَجَعَلُوا فِي عُنُقِهِ وَعُنُقِهَا حَبْلًا وَجَعَلُوا يَطُوفُونَ بِهِمَا فِي النَّاسِ فَوَضَعَ أُصْبُعَهُ عَلَى بَطْنِهَا فَقَالَ أَيْ غُلَامُ مَنْ أَبُوكَ قَالَ أَبِي فُلَانٌ رَاعِي الضَّأْنِ فَقَبَّلُوهُ وَقَالُوا إِنْ شِئْتَ بَنَيْنَا لَكَ ‏ ‏الصَّوْمَعَةَ ‏ ‏مِنْ ذَهَبٍ وَفِضَّةٍ قَالَ أَعِيدُوهَا كَمَا كَانَتْ ‏","","",""],[8634,8634,"","আমরা সেই সময়ের কথা বলেছিলাম যারা তাদের জীবন হারিয়েছে, আমি এটা করতে রাজি আছি, সে এটা ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْلَسَ الرَّجُلُ فَوَجَدَ ‏ ‏غَرِيمُهُ ‏ ‏مَتَاعَهُ عِنْدَ الْمُفْلِسِ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[8635,8635,"","আমার বাবা মানে আমার বাবার সবচেয়ে ছোট ঘোড়া আর তিনি তার জন্য ঈশ্বরের কাছে প্রার্থনা করেন । তাদের কাপড় থেকে ধরা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خِلَاسِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ يَعْنِي الصَّائِغَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمُؤْمِنِ زَوْجَتَانِ يُرَى مُخُّ ‏ ‏سُوقِهِمَا ‏ ‏مِنْ فَوْقِ ثِيَابِهِمَا ‏","","",""],[8636,8636,"","আমার বাবা তার কাছে যে - বিষয়টা চেয়েছিলেন, তা হল, ভাববাদী তাকে আদেশ দিয়েছেন এবং তাঁর শক্তিতে যারা আছেন তাদেরকে রক্ষা করবেন । - খুন হয়েছে, স্নাইপার নেই।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اطَّلَعَ فِي بَيْتِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ فَفَقَئُوا عَيْنَهُ فَلَا ‏ ‏دِيَةَ ‏ ‏لَهُ وَلَا ‏ ‏قِصَاصَ ‏","","",""],[8637,8637,"","আমার বাবা তার জন্য প্রার্থনা করেছিলেন এবং তিনি তার দয়ায় আশীর্বাদকে ভালবাসেন না বলে তাকে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8638,8638,"","বাবা হারাহর কথা শোন বাবা হারাহ বলছে যে ঈশ্বর তার জন্য প্রার্থনা করেছে এবং আমার জীবন দান করেছে। সুস্থ হওয়ার মানে হলো বিক্রি করা আর উড়তে থাকা।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو صَفْوَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمَدِينَةِ ‏ ‏لَتَتْرُكَنَّهَا عَلَى خَيْرِ مَا كَانَتْ مُذَلَّلَةً ‏ ‏لِلْعَوَافِي ‏ ‏يَعْنِي السِّبَاعَ وَالطَّيْرَ ‏","","",""],[8639,8639,"","আমি ঈশ্বরকে তার পরিচিত করে বলতে শুনেছি, তিনি তাকে জানতেন এবং তিনি বলতেন যে তিনি কখনই আমাকে ছেড়ে দেবেন না। আমার মেয়ের উত্তর থেকে আমাকে রক্ষা করো.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَرْتَقِيَنَّ جَبَّارٌ مِنْ جَبَابِرَةِ ‏ ‏بَنِي أُمَيَّةَ ‏ ‏عَلَى مِنْبَرِي هَذَا ‏","","",""],[8640,8640,"","আমার বাবার সাথে যা ঘটেছে, আমরা তার ব্যাপারে কথা বলেছি। আল্লাহ তাঁর কাছে প্রার্থনা করেছেন এবং হামাদাহের কথাগুলো আত্মসমর্পণ করেছেন এবং তাঁর কাছে যে ভবিষ্যদ্বাণী তা থেকে ভালো প্রমাণিত হয়েছে এবং তাকে উদ্ধার করেছেন। স্যামকে তার শান্তির জন্য প্রস্তুত করা হয়েছে, কিন্তু তার দুঃখ থেকে তাকে ক্ষমা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَثَابِتٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ ‏","","",""],[8641,8641,"","আমরা আমার ভাই হারিরির কথা বলেছিলাম যে সে হয়ত সত্য শুনেছে, সে বলবে লর্ডের হাতে তার মনের কথা আছে তার মাথা.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنْ مِنْكُمْ مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ وَفَضْلٍ وَوَضَعَ يَدَهُ عَلَى رَأْسِهِ ‏","","",""],[8642,8642,"","আমরা একটা বাপ্তিস্মের মাধ্যমে আহত হয়েছি, যার মানে আমার বাবা দেবীর দ্বারা বাপ্তাইজিত একজন ছেলে, সে ছেলেটাকে পালিয়ে পালিয়ে পাথরের বেশ্যায় পরিণত করেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[8643,8643,"","আমরা আমার বাবা একজন উৎপীড়ক ছিলেন যিনি তার কাছে প্রার্থনা শুনেছেন, তিনি বলেন তিনি ঈশ্বরের দিকে তাকান না যে তার সফর পরিচালনা করছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8644,8644,"","আমরা আমার বাবাকে ঈশ্বরের কাছে এত আশীর্বাদ পাওয়ার বিষয়ে বলেছিলাম যে, তিনি ঈশ্বরের প্রতি এত স্বপ্ন ছিলেন যে, তিনি ঈশ্বরের প্রতি এতটাই স্বপ্ন ছিলেন যে, তিনি হলেন, ভাল, বিয়ার এবং এরপর বিয়ার ও পঞ্চম মৃগীরোগী ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمْسُ ‏","","",""],[8645,8645,"","আমরা বাবার ঈশ্বরের উপহারের জন্য আমার বাবার একজন মাষ্টারের প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, যে রোগীকে কিনেছে তাকে পাশ থেকে বাধা দেবার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ ‏ ‏بِالْخِيَارِ ‏ ‏إِنْ شَاءَ رَدَّهَا ‏ ‏وَصَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[8646,8646,"","আমরা আমার বাবাকে জিতিয়ে আমার বাবাকে একটা নরক দিতে বলেছিলাম, ঈশ্বর তা উদ্ধার করতে হবে, সে গম চুরি করবে না এবং সে সুরক্ষিত থাকবে না। সে নিরাপদ, একটা গোপন ভাবে বের হয়ে বললো তাকে তার নিজের অধিকার থেকে সরিয়ে নিতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَعَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ وَلَا يَزْنِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَغُلُّ ‏ ‏حِينَ ‏ ‏يَغُلُّ ‏ ‏وَهُوَ مُؤْمِنٌ وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏حِينَ ‏ ‏يَنْتَهِبُ ‏ ‏وَهُوَ مُؤْمِنٌ ‏ ‏وَقَالَ ‏ ‏عَطَاءٌ ‏ ‏وَلَا ‏ ‏يَنْتَهِبُ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ شَرَفٍ وَهُوَ مُؤْمِنٌ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَقِيلَ لَهُ قَالَ إِنَّهُ يُنْتَزَعُ مِنْهُ الْإِيمَانُ فَإِنْ تَابَ تَابَ اللَّهُ عَلَيْهِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَفِي حَدِيثِ ‏ ‏عَطَاءٍ ‏ ‏نُهْبَةً ‏ ‏ذَاتَ شَرَفٍ وَهُوَ مُؤْمِنٌ ‏","","",""],[8647,8647,"","আমরা সাহায্য করার চেষ্টা করেছি কিন্তু সাহায্য করার চেষ্টা করেছি। ঈশ্বরের দোহাই তাকে ধরে নিয়ে গেছে। সে বলবে আমরা কি এক বন্ধুকে তার মুখ থেকে কেটে ফেলেছি। আর তুমি কি করছ তা নিয়ে আমরা একসাথে কথা বলছি। আর তুমি কি করছ? ঈশ্বরের জয় হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا نَقَصَتْ ‏ ‏صَدَقَةٌ ‏ ‏مِنْ مَالٍ وَمَا زَادَ اللَّهُ رَجُلًا بِعَفْوٍ إِلَّا عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[8648,8648,"","আর এটা প্রভুর বার্তাবাহকের জেগে ওঠার পর, ঈশ্বর তাকে আদেশ দিয়েছেন যে, সে কি চায়, সে কি করতে পারে? তোমার ভাই বলবে ঈশ্বর আপনার ভাইয়ের মধ্যে আছেন। মুখে, সে বলেছিল ওকে হারিয়ে ফেলবে।","‏ ‏وَبِهَذَا الْإِسْنَادِ وَاللَّفْظِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قِيلَ لَهُ مَا الْغِيبَةُ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏ذِكْرُكَ أَخَاكَ بِمَا يَكْرَهُ قَالَ أَفَرَأَيْتَ إِنْ كَانَ فِي أَخِي مَا أَقُولُ أَيْ رَسُولَ اللَّهِ قَالَ إِنْ كَانَ فِي أَخِيكَ مَا تَقُولُ فَقَدْ ‏ ‏اغْتَبْتَهُ ‏ ‏وَإِنْ لَمْ يَكُنْ فِيهِ مَا تَقُولُ فَقَدْ ‏ ‏بَهَتَّهُ ‏","","",""],[8649,8649,"","আমরা তার কাছে ফিরে যাওয়ার কথা বলছিলাম, বাবা তার নিজের ছবি খুঁজে পাবার কথা শুনেছেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ছায়ার কাছে আত্মসমর্পণ করেছেন এবং তারপর তাকে দয়া থেকে কম বলেছিলেন। তাহলে তুমি তোমার আগের থেকে আরও দুটো খুজে পেয়েছ.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ رَكْعَتَيْنِ ثُمَّ سَلَّمَ قَالُوا قَصُرَتْ الصَّلَاةُ قَالَ فَقَامَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ بَعْدَ مَا سَلَّمَ ‏","","",""],[8650,8650,"","ঈশ্বর আদেশ দিয়েছিলেন এবং প্রার্থনা করে লোকেদের কাছে পৌঁছে দেওয়ার জন্য আমি তাদের সেবা করেছি । হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتُوا الصَّلَاةَ وَعَلَيْكُمْ ‏ ‏السَّكِينَةُ ‏ ‏فَصَلُّوا مَا أَدْرَكْتُمْ وَاقْضُوا مَا سَبَقَكُمْ ‏","","",""],[8651,8651,"","আমি আমার ভাই হাররির সঙ্গে কথা বলার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْكَعْبَةَ ‏","","",""],[8652,8652,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং হঠাৎ করে যদি যোদ্ধার সঙ্গে যুদ্ধ করতে হয়, তা হলে তিনি আত্মসমর্পণ করেছিলেন । বিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا بَاتَتْ الْمَرْأَةُ هَاجِرَةً فِرَاشَ زَوْجِهَا لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تَرْجِعَ ‏","","",""],[8653,8653,"","বাবার ভালবাসা নিয়ে আমরা কথা বলেছিলাম, আমি আমার চাচার কথা শুনেছি। আমার ভাইয়ের প্রতি তার বাবার লোভ একজন দেবতা মানুষ যে আমাকে জিজ্ঞেস করেছে, ঈশ্বর এসব গ্রহণ করেননি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ فِي غَيْرِ رُخْصَةٍ رَخَّصَهَا اللَّهُ لَهُ فَلَنْ يُقْبَلَ مِنْهُ الدَّهْرَ كُلَّهُ ‏","","",""],[8654,8654,"","আমার বাবার সাথে জেদি আচরণ করে আমি আমার বাবার সাথে কথা বলেছি, আমি কে, ঈশ্বর আমাকে আশীর্বাদ করেছেন। তোমার ভাগ্য, সে যদি তোমাকে বলে, আমরা তাকে বাঁচাতে পারি, তারা ফিরে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏وَقَالَ ‏ ‏أَبُو عَوَانَةَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ الْأَمِيرَ فَقَدْ أَطَاعَنِي وَمَنْ عَصَى الْأَمِيرَ فَقَدْ عَصَانِي وَالْأَمِيرُ ‏ ‏مِجَنٌّ ‏ ‏فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ إِذَا وَافَقَ ذَلِكَ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَكُمْ وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا ‏","","",""],[8655,8655,"","আমরা একটা বাপ্তিস্মের কথা বলেছি যেটা ঈশ্বরের অনুগ্রহের জন্য জন্ম দিয়েছে। তিনি প্রভুর কাছে প্রার্থনা করেছিলেন এবং বলতেন যে, কে এসেছে। এটা দেখে মনে হচ্ছে বাবার কী হবে, সে তার মন হারিয়ে ফেলেছে, সে তার হাত নিয়ে তার বাবার সাথে যাবে, আর সে মেরে ফেলবে ঈশ্বরের অনুগ্রহ কখনো তাকে লর্ডের ডিপোজিট করতে দেয়নি... ...এবং সে এই দুর্দশার জন্য আত্মসমর্পণ করেছে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ صَلَّى عَلَى جِنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا وَتَبِعَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏انْظُرْ مَا تُحَدِّثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَإِنَّك تُكْثِرُ الْحَدِيثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ بِيَدِهِ فَذَهَبَ بِهِ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَصَدَّقَتْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاللَّهِ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏مَا كَانَ يَشْغَلُنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّفْقُ فِي الْأَسْوَاقِ مَا كَانَ يُهِمُّنِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا كَلِمَةً يُعَلِّمُنِيهَا أَوْ لُقْمَةً يَلْقُمُنِيهَا ‏","","",""],[8656,8656,"","আমরা আমার ভাইয়ের পঞ্চম ভাগ থেকে ভাল পেতে চাই, তাকে গান দিতে হবে যতক্ষণ না একে অপরকে মুক্ত করে দেওয়া হয়।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدِ بْنِ خُمَيْرٍ ‏ ‏عَنْ ‏ ‏مَوْلًى ‏ ‏لِقُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعِ الْغَنَائِمِ حَتَّى تُقْسَمَ وَعَنْ بَيْعِ الثَّمَرَةِ حَتَّى ‏ ‏تُحْرَزَ ‏ ‏مِنْ كُلِّ ‏ ‏عَارِضٍ ‏ ‏وَأَنْ يُصَلِّيَ الرَّجُلُ حَتَّى ‏ ‏يَحْتَزِمَ ‏","","",""],[8657,8657,"","আমরা আমার বাবাকে একজন পলাতক হিসেবে নিয়ে কথা বলেছিলাম, যাকে তার জীবনের জন্য লড়াই করতে হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا شَكَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْوَةَ قَلْبِهِ فَقَالَ ‏ ‏امْسَحْ رَأْسَ الْيَتِيمِ وَأَطْعِمْ الْمِسْكِينَ ‏","","",""],[8658,8658,"","আমার বাবার সাথে আমার ছেলের মত কথা বলেছি। তিনি আমার ছেলেকে মুক্ত করার ব্যাপারে কথা বলেছেন। তিনি জিজ্ঞেস করেছেন, কে এর মধ্যকার অসুস্থ হয়ে পড়েছেন। দুই জায়গা.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ مِنْ الْأَرْضِ شِبْرًا بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[8659,8659,"","আমি আমার বাবার সাথে আমার ছেলের মত কথা বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هُنَّ أَيَّامُ ‏ ‏طُعْمٍ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏يَعْنِي ‏ ‏أَيَّامَ التَّشْرِيقِ ‏","","",""],[8660,8660,"","আর এই শিকারী বলেছে, ভালো কথা হচ্ছে পৃথিবীর ভালোর তিনগুণ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ ‏ ‏مَا ‏ ‏الطِّيَرَةُ ‏ ‏قَالَ لَا ‏ ‏طَائِرَ ‏ ‏ثَلَاثَ مَرَّاتِ وَقَالَ خَيْرُ الْفَأْلِ الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[8661,8661,"","আমি যদি তোমার কথা শুনে থাকি তাহলে তুমি সেটা করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ أَحَدُكُمْ الْإِقَامَةَ فَلْيَأْتِ عَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏فَمَا أَدْرَكَ فَلْيُصَلِّ وَمَا فَاتَهُ فَلْيُتِمَّ ‏","","",""],[8662,8662,"","আর এই শিকারী বলেছে যে ভগবানের কাছে প্রার্থনা করছে আর ভগবানের দোহাই দিয়ে আল্লাহকে রক্ষা করেছে।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ الرَّاشِيَ وَالْمُرْتَشِيَ فِي الْحُكْمِ ‏","","",""],[8663,8663,"","আর সেই ভাববাদীর জন্য ফোন এসেছে তাকে দেখাতে... ...আর যদি কেউ দেখাতে চায় তাহলে সে আত্মসমর্পণ করবে.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَمَنَّى أَحَدُكُمْ فَلْيَنْظُرْ مَا الَّذِي يَتَمَنَّى فَإِنَّهُ لَا يَدْرِي مَا الَّذِي يُكْتَبُ لَهُ مِنْ أُمْنِيَّتِهِ ‏","","",""],[8664,8664,"","আর এই যে সেই ভাববাদীর ডাক, যে তাকে আদেশ দিয়েছে... ...আর বলেছে যে আমরা প্রেম করি আর ভালবাসি। এই চতুর্থ মাসের মধ্যে আমরা যা করেছি তা হলো, বাবার সিঁড়ির.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏أُحُدًا ‏ ‏هَذَا جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فِيهَا كُلِّهَا فِي هَذِهِ الْأَرْبَعَةِ قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏","","",""],[8665,8665,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং তাঁকে আত্মসমর্পণ করেছিলেন, নৌকা থেকে নিয়ে লর্ডকে রক্ষা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذُوا مِنْ الشَّوَارِبِ وَأَعْفُوا اللِّحَى ‏","","",""],[8666,8666,"","আর এই শিকারী সৃষ্টিকর্তাকে তার সাহায্য চাইতে বলেছে, ঈশ্বর বলেছেন আমার বাবা আমাকে হারিয়ে ফেলেছেন। যে আমাকে ছেড়ে দিয়েছে সে ঈশ্বরের সমবেদনা জানিয়েছে, সে ছিল আমার বাবা আমার বাবা আমার জন্য একটি ঘোড়া। কান হারিয়ে আমি চেষ্টা হারিয়ে ফেলি, কুশন জন্ম নেয় নি এবং যথেষ্ট ছিল না।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُونَ يَسْأَلُونَ حَتَّى يُقَالُ هَذَا اللَّهُ خَلَقَنَا فَمَنْ خَلَقَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَوَاللَّهِ إِنِّي لَجَالِسٌ يَوْمًا إِذْ قَالَ لِي رَجُلٌ مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏هَذَا اللَّهُ خَلَقَنَا فَمَنْ خَلَقَ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَجَعَلْتُ أُصْبُعَيَّ فِي أُذُنَيَّ ثُمَّ صِحْتُ فَقُلْتُ صَدَقَ اللَّهُ وَرَسُولُهُ اللَّهُ الْوَاحِدُ ‏ ‏الصَّمَدُ ‏ ‏لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ ‏ ‏كُفُوًا ‏ ‏أَحَدٌ ‏","","",""],[8667,8667,"","( যোহন ১৭: ৩) আর এই আহ্বান ঈশ্বরের কাছে প্রার্থনা করার মাধ্যমে তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন যে, তাঁকে তাঁর কাছে দেওয়া হবে, যেন তিনি ঈশ্বরের কাছে মুক্তি লাভ করেন, যিনি তাঁর জয় লাভ করেন এবং তাঁর কাছে ক্ষমা চান ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَغَارُ وَمِنْ غَيْرَةِ اللَّهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حُرِّمَ عَلَيْهِ ‏","","",""],[8668,8668,"","বাবা আমার বাবাকে ফেলে দেওয়ার চেষ্টা করার বিষয়ে আমরা বাবার সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏أَحَدُكُمْ ‏ ‏فَلْيُوتِرْ ‏","","",""],[8669,8669,"","আমরা আমার বাবার সাথে আমার ছেলের মত কথা বলেছিলাম, সে যদি খেলা চালিয়ে যায় আর বলতো যে সে চুরি করে অর্ধেক সময়ে টাকা ভরে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَبَقَ ‏ ‏الْعَبْدُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً إِذَا سَرَقَ ‏ ‏فَبِعْهُ وَلَوْ ‏ ‏بِنَشٍّ ‏ ‏وَالنَّشُّ نِصْفُ الْأُوقِيَّةِ ‏","","",""],[8670,8670,"","বাবা আমার বাবার সাথে কথা বলতে চায়, ঈশ্বরের খারাপ অবস্থা তার বাবার কাছে আর আদালতে আল-ফাদার কথা বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ الرَّاشِيَ وَالْمُرْتَشِيَ فِي الْحُكْمِ ‏","","",""],[8671,8671,"","ঈশ্বর তিনটে বিষয় জুগিয়েছেন, সেগুলোর মধ্যে সবই উত্তম শিক্ষক হওয়ার অধিকার রয়েছে, তাদের মধ্যে একজন হলেন সেই ব্যক্তি যিনি হলেন যিহোবা । যে ব ্ যক ্ তি উপুড় হয়ে পড়ে এবং বলে , এটাই তো সেই জন , যে-ই জন ্ যে সমান । ঈশ্বর জয়ী হয়েছেন এবং তা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ كُلُّهُنَّ حَقٌّ عَلَى كُلِّ مُسْلِمٍ ‏ ‏عِيَادَةُ ‏ ‏الْمَرِيضِ وَشُهُودُ الْجِنَازَةِ ‏ ‏وَتَشْمِيتُ ‏ ‏الْعَاطِسِ إِذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[8672,8672,"","আমি আমার বাবার সাথে আমার ভাইকে মুক্ত করার কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثَرُ عَذَابِ الْقَبْرِ فِي الْبَوْلِ ‏","","",""],[8673,8673,"","আমরা ইশ্বরের কথা বলেছিলাম যখন আমার ছেলে দেবী ছিলেন তখন তার সাথে কথা বলেছিলাম. সে বলবে যে সে ঈশ্বরকে ধন্যবাদ দেয়না.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[8674,8674,"","আমি আনন্দিত যে আমার টাকা ঈশ্বরের ঋণের টাকা নেই। তার টাকা না.","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَأَشْجَعُ ‏ ‏مَوَالِيَّ ‏ ‏لَيْسَ لَهُمْ دُونَ اللَّهِ وَلَا رَسُولِهِ ‏ ‏مَوْلًى ‏","","",""],[8675,8675,"","এরপর তিনি আমার বাবার কাছে ভবিষ্যদ্বাণী করার এক উপহার হিসেবে কাজ করেছিলেন এবং ঈশ্বর আমাকে উদ্ধার করেছেন । বাবা লর্ডের একজন পলাতক, যে তার ইচ্ছা রক্ষা করতে চায়, আমি তার ডানার একজন আর অন্যটা সবসময় বলে যে একবার তার নিজের একটাকে ছেড়ে দিতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً قَالَ زَعَمَ ذَاكَ ‏ ‏ثُمَامَةُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَلْيَغْمِسْهُ فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَالْآخَرِ دَوَاءً ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فَإِنَّ أَحَدَ جَنَاحَيْهِ ‏","","",""],[8676,8676,"","ভালোর জন্য মরে যাওয়া হবে, তার ঈশ্বর তাকে হারিয়ে ফেলতে বলেছিলেন এবং তাকে হত্যা করতে বলেছিলেন । ভালো যে বলেছিল সে মারা গেছে... ...যদি আমাকে মারতে বলা হতো... ...সে বলত যে সে বলবে যে সে অবশ্যই বলবে যে সে হবে। তার মানে এই নয় যে তাকে বলতেই হবে যে, তাকে বলতেই হবে যে, তাকে বলতেই হবে যে, তাকে বলতেই হবে যে, সে অবশ্যই বলবে যে, সে অবশ্যই বলবে যে তার কিছু আছে অথবা তার কোন কিছু আছে। আমার প্রার্থনা তাদের কাছে রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏إِنْسَانًا ‏ ‏كَانَ ‏ ‏يَقُمُّ ‏ ‏الْمَسْجِدَ أَسْوَدَ مَاتَ ‏ ‏أَوْ مَاتَتْ ‏ ‏فَفَقَدَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا فَعَلَ الْإِنْسَانُ الَّذِي كَانَ ‏ ‏يَقُمُّ ‏ ‏الْمَسْجِدَ قَالَ فَقِيلَ لَهُ مَاتَ قَالَ فَهَلَّا ‏ ‏آذَنْتُمُونِي ‏ ‏بِهِ فَقَالُوا إِنَّهُ كَانَ لَيْلًا قَالَ فَدُلُّونِي عَلَى قَبْرِهَا قَالَ فَأَتَى الْقَبْرَ فَصَلَّى عَلَيْهَا ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏عِنْدَ ذَاكَ أَوْ فِي حَدِيثٍ آخَرَ ‏ ‏إِنَّ هَذِهِ الْقُبُورَ مَمْلُوءَةٌ ظُلْمَةً عَلَى أَهْلِهَا وَإِنَّ اللَّهَ عَزَّ وَجَلَّ يُنَوِّرُهَا بِصَلَاتِي عَلَيْهِمْ ‏","","",""],[8677,8677,"","আমি আমার বাবার সম্বন্ধে কথা বলেছিলাম, যিনি তার সম্বন্ধে জানতে চান । আমি যদি যেতে না পারতাম, তাহলে আমি যদি যেতে পারতাম, আমি বলতে পারতাম না যে তুমি হারিয়ে যেতে অথবা যেতে পারবে । খারাপ লোক একজন ভালো বন্ধু, তুমি তাকে শ্বাস নিতে বিশ্বাস করো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَلِيفَةُ بْنُ غَالِبٍ اللَّيْثِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عِنْدَهُ فَسَأَلَهُ فَقَالَ يَا نَبِيَّ اللَّهِ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ الْإِيمَانُ بِاللَّهِ وَالْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ فَإِنْ لَمْ أَسْتَطِعْ ذَاكَ قَالَ فَأَيُّ الرِّقَابِ أَعْظَمُ أَجْرًا قَالَ أَغْلَاهَا ثَمَنًا وَأَنْفَسُهَا عِنْدَ أَهْلِهَا قَالَ فَإِنْ لَمْ أَسْتَطِعْ قَالَ ‏ ‏فَتُعِينُ ‏ ‏ضَائِعًا أَوْ تَصْنَعُ ‏ ‏لِأَخْرَقَ ‏ ‏قَالَ فَإِنْ لَمْ أَسْتَطِعْ ذَاكَ قَالَ فَاحْبِسْ نَفْسَكَ عَنْ الشَّرِّ فَإِنَّهَا ‏ ‏صَدَقَةٌ ‏ ‏حَسَنَةٌ تَصَدَّقْتَ بِهَا عَلَى نَفْسِكَ ‏","","",""],[8678,8678,"","ঈশ্বর প্রথমে যে - বিষয়গুলো করেছিলেন, সেগুলো তাকে দিয়ে দিয়েছিলেন আর শুধুমাত্র কষ্টভোগ করার জন্য তিনি যা করেছিলেন, সেগুলোই তাকে দিয়েছিলেন । যদি সে উপরে তুলে নেয় বা ভয় পায়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عِسْلُ بْنُ سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا طَلَعَ النَّجْمُ صَبَاحًا قَطُّ وَتَقُومُ ‏ ‏عَاهَةٌ ‏ ‏إِلَّا رُفِعَتْ عَنْهُمْ أَوْ خَفَّتْ ‏","","",""],[8679,8679,"","আমার ভাই হার্বারের কথা বলেছিলাম, আর আমরা তার কথা শুনেছি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ صَوْتًا فَأَعْجَبَهُ فَقَالَ ‏ ‏قَدْ أَخَذْنَا فَالَكَ مِنْ ‏ ‏فِيكَ ‏","","",""],[8680,8680,"","আমরা দুই মাস আগে মা ছাড়া পাওয়ার কথা বলেছিলাম। সে তার মায়ের কাছে প্রার্থনা করেছিল। সে তার জন্য প্রার্থনা করতো এবং তার মৃত্যুর আগে যাকে সে লিখেছে, আমরা সেভাবেই লিখেছে। আমরা এখন আছি। কালকের মধ্যে বিক্রি হবেনা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏أُمِّ بُرْثُنٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ اللَّهُ الْجُمُعَةَ عَلَى مَنْ كَانَ قَبْلَنَا فَاخْتَلَفُوا وَهَدَانَا اللَّهُ لَهَا فَالنَّاسُ لَنَا فِيهَا تَبَعٌ ‏ ‏فَلِلْيَهُودِ ‏ ‏غَدٌ ‏ ‏وَلِلنَّصَارَى ‏ ‏بَعْدَ غَدٍ ‏","","",""],[8681,8681,"","আমরা আমার বাবা দেবী হওয়ার কথা বলেছিলাম তিনি বলেছিলেন আপনি সুলতানের পাশে থাকেন নি পবিত্র পিতার গৃহ থেকে পালিয়ে যেতে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ فَإِنَّ الشَّيْطَانَ يَفِرُّ مِنْ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ ‏ ‏الْبَقَرَةُ ‏","","",""],[8682,8682,"","আর এই অদ্ভুত কল তাকে আদেশ দিয়েছে... ...আর সে যদি কথা বলে, প্রভু সূর্যয় হারিয়ে যায়...","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَكَلَّمْتَ يَوْمَ الْجُمُعَةِ فَقَدْ ‏ ‏لَغَوْتَ ‏ ‏وَأَلْغَيْتَ ‏","","",""],[8683,8683,"","আর এই আহ্বানের মাধ্যমে নবী তার কাছে প্রার্থনা করেন এবং তাকে আত্মসমর্পণ করেন যে আগুন থেকে পানীয় পান করে, আমি অসুস্থ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ شِبْرًا مِنْ الْأَرْضِ بِغَيْرِ حَقِّهِ ‏ ‏طُوِّقَهُ ‏ ‏مِنْ سَبْعِ أَرَضِينَ ‏","","",""],[8684,8684,"","আর এই আহ্বানই ভাববাদীর কাছে প্রার্থনা করেছিলেন এবং তিনি কখনোই মারা যেতে পারবেন না ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَسْتُرُ عَبْدٌ عَبْدًا فِي الدُّنْيَا إِلَّا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ‏","","",""],[8685,8685,"","এই অদ্ভুত আহ্বান তাকে আদেশ দিয়েছে আর আত্মসমর্পণ করবে আর আগুন জ্বালিয়ে দিবে.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏فِيهَا كُلِّهَا حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏هَكَذَا قَالَهَا أَبِي ‏","","",""],[8686,8686,"","আমরা হামাদের ব্যাপারে কথা বলেছি কিন্তু সে বলেছিল যে আমরা আমার বাবা জিনিয়াস হতে কথা বলব, ঈশ্বরের কাছে প্রার্থনা করবে আর যদি সে তোমাকে তার কোর্ট থেকে ফিরিয়ে নিয়ে যায় অবশ্যই.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَوُهَيْبٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[8687,8687,"","আমরা আমার বাবার সঙ্গে দেবী হিসেবে আচরণ করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَأَنْ يَجْلِسَ أَحَدُكُمْ عَلَى جَمْرَةٍ فَتُحْرِقَ ثِيَابَهُ حَتَّى تَخْلُصَ إِلَيْهِ خَيْرٌ مِنْ أَنْ يَطَأَ عَلَى قَبْرِ رَجُلٍ مُسْلِمٍ ‏","","",""],[8688,8688,"","এই অদ্ভুত উক্তি তার কাছে প্রার্থনা করেছে এবং তাকে অতীতের কিছু শিল্প এবং মাথা উঁচু করে ফেলার জন্য দেওয়া হয়েছে।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفَ شَاةٍ فَمَضْمَضَ وَغَسَلَ يَدَهُ وَصَلَّى ‏","","",""],[8689,8689,"","সেই আহ্বানই ভাববাদীর কাছে প্রার্থনা করেছিলেন আর সেই দিনই আমি তার জন্মের দিন হাল ছেড়ে দেব ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ ‏ ‏ثَوْرَ ‏ ‏أَقِطٍ ‏ ‏فَتَوَضَّأَ مِنْهُ وَصَلَّى ‏","","",""],[8690,8690,"","( ১ রাজাবলি ১৭: ৩) আর এই আহ্বানই ভাববাদীর কাছে প্রার্থনা করে তিনি বলবেন যে, আপনি রেগে যাবেন না এবং বলবেন যে, আপনি রেগে যাবেন না এবং তা করবেন না ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَرُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[8691,8691,"","আর এই ন্যাট লর্ডকে উদ্ধার করার জন্য সে যা বলেছে, কখনো তোমার কথা বলেনি, তুমি বাঁশের তরবারি দিয়ে ভেঙ্গেছ, আর তোমার বসার হাঁস।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا اجْتَمَعَ قَوْمٌ فَتَفَرَّقُوا عَنْ غَيْرِ ذِكْرِ اللَّهِ إِلَّا كَأَنَّمَا تَفَرَّقُوا عَنْ جِيفَةِ حِمَارٍ وَكَانَ ذَلِكَ الْمَجْلِسُ عَلَيْهِمْ ‏ ‏حَسْرَةً ‏","","",""],[8692,8692,"","আর এই ধরনের এক অপ্রত্যাশিত আহ্বানকে তার কাছে করা হয়েছে এবং তাকে উদ্ধার করা হবে ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُفْتَحُ أَبْوَابُ السَّمَاءِ كُلَّ يَوْمِ اثْنَيْنِ وَخَمِيسٍ فَيُغْفَرُ ذَلِكَ الْيَوْمَ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللَّهِ شَيْئًا إِلَّا امْرَأً كَانَ بَيْنَهُ وَبَيْنَ أَخِيهِ ‏ ‏شَحْنَاءُ ‏ ‏فَيُقَالُ ‏ ‏أَنْظِرُوا ‏ ‏هَذَيْنِ حَتَّى يَصْطَلِحَا ‏","","",""],[8693,8693,"","আমি যখন ঘরে ফিরে আসি, তখন আমি আমার বাবার প্রতি করুণা দেখানোর বিষয়ে কথা বলি । চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الدِّينَ بَدَأَ غَرِيبًا وَسَيَعُودُ غَرِيبًا كَمَا بَدَأَ ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ ‏","","",""],[8694,8694,"","আর এটাই ঈশ্বরের দোহাই, ঈশ্বর আদেশ দিয়েছেন, আর তিনি ত্রাণকর্মীর জেল থেকে ঋণ ফিরিয়ে দিয়েছেন।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ ‏","","",""],[8695,8695,"","আমরা সাহায্য করার কথা বলেছিলাম কিন্তু সে আমাদের সম্পর্কে কতটুকু কথা বলেছে তা জানতে চেষ্টা করলাম। আমার বাবা ঈশ্বরের ইচ্ছা থেকে পলাতক, ঈশ্বর তাকে বলেছিলেন যেন তার প্রেমে না বলি।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ الْقَاصُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ دَاءٍ إِلَّا فِي الْحَبَّةِ السَّوْدَاءِ مِنْهُ شِفَاءٌ إِلَّا ‏ ‏السَّامُ ‏","","",""],[8696,8696,"","আমাদের কথাবার্তা আর বাবা ঈশ্বরের প্রতি ঈর্ষা প্রকাশ করেছে, সে বলত, তার লোকেরা যেন কল্পনার মতো, তুমি সবাইকে জেলে ভরে রাখো। যে বন্ধুত্বের মাধ্যমে রাজত্বের প্রভাব থেকে মুক্তি পেতে সাহায্য করেছে, তার প্রতিটি কোণ তার সম্পর্কে আমাকে বলতে হবে, এটা ছড়িয়ে দিন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الْبَخِيلِ وَالْمُتَصَدِّقِ مَثَلُ رَجُلَيْنِ عَلَيْهِمَا ‏ ‏جُبَّتَانِ ‏ ‏مِنْ حَدِيدٍ قَدْ ‏ ‏اضْطُرَّتْ ‏ ‏أَيْدِيهِمَا إِلَى ‏ ‏تَرَاقِيهِمَا ‏ ‏فَكُلَّمَا هَمَّ الْمُتَصَدِّقُ ‏ ‏بِصَدَقَةٍ ‏ ‏اتَّسَعَتْ عَلَيْهِ حَتَّى ‏ ‏تُعَفِّيَ ‏ ‏أَثَرَهُ ‏ ‏وَكُلَّمَا هَمَّ الْبَخِيلُ ‏ ‏بِصَدَقَةٍ ‏ ‏انْقَبَضَتْ عَلَيْهِ كُلُّ حَلْقَةٍ مِنْهَا إِلَى صَاحِبَتِهَا وَتَقَلَّصَتْ عَلَيْهِ قَالَ فَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي يَقُولُ فَيَجْهَدُ أَنْ يُوَسِّعَهَا فَلَا تَتَّسِعُ ‏","","",""],[8697,8697,"","তারা বলেছিল, ঈশ্বর আমাদের প্রিয় মানুষকে দেখেছেন এবং আপনার মতো হবেন । তোমার ইচ্ছা সিদ্ধ হউক, তোমার ইচ্ছা সিদ্ধ হউক, যেমন তুমি তোমার ইচ্ছা সিদ্ধ হউক, তেমনি তোমার ইচ্ছা সিদ্ধ হউক । আর তুমি যা করতে চাও, তা তোমার ইচ্ছাই হবে তোমার । আর তারা বলে যে তোমার চাঁদ তোমাকে জলাঞ্জলি দেবে । দিনের বেলায়, আকাশের দিকে নয়, তারা বলেছিল, আমরা তাকে মেরে ফেলবো। আর তুমি তাকে দেখে কষ্ট পাও না।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ مُحَمَّدِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏أَنَرَى رَبَّنَا عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ قَالَ هَلْ تَرَوْنَ الشَّمْسَ بِنِصْفِ النَّهَارِ لَيْسَ فِي السَّمَاءِ سَحَابَةٌ قَالُوا نَعَمْ قَالَ هَلْ تَرَوْنَ الْقَمَرَ لَيْلَةَ الْبَدْرِ لَيْسَ فِي السَّمَاءِ سَحَابَةٌ قَالُوا نَعَمْ قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَتَرَوُنَّ اللَّهَ عَزَّ وَجَلَّ وَلَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِ كَمَا لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِمَا ‏","","",""],[8698,8698,"","আমার বাবার সাথে আমার ভাইকে মুক্ত করার কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَكْثَرَ عَذَابِ الْقَبْرِ مِنْ الْبَوْلِ ‏","","",""],[8699,8699,"","আমরা আমার বাবার স্বপ্নের কথা বলেছিলাম... ...তার কাছে প্রার্থনা করার সময়... ...তিনি তাকে ছেড়ে দিবেননা. যদি আমি তাড়াতাড়ি ক্ষমা করে ফেলি","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَاسْأَلْهُ مَا ‏ ‏بَالُ ‏ ‏النِّسْوَةِ اللَّاتِي قَطَّعْنَ أَيْدِيَهُنَّ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كُنْتُ أَنَا لَأَسْرَعْتُ الْإِجَابَةَ وَمَا ابْتَغَيْتُ الْعُذْرَ ‏","","",""],[8700,8700,"","বাবার ছেলের কথা বলেছিলাম, আর সে মনে হচ্ছিল আমার বাবা চোর। আমার বাবা যে একজন যাজক, তার কাছে আমি আশীর্বাদ নিয়ে এসেছি। গায়কের সাথে বন্ধুত্ব, তাই আবার,","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏وَيَحْيَى بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَصِينٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لَغَنِيٍّ وَلَا لِذِي ‏ ‏مِرَّةٍ ‏ ‏سَوِيٍّ ‏","","",""],[8701,8701,"","বাবা যখন আমার বিড়ালের কথা বলছিল তখন আমরা কয়েক বছর আগে কথা বলেছিলাম, ঈশ্বরের ইচ্ছা ছিল সে প্রার্থনা করবে, আর সে লক্ষণগুলো নিয়ে এত গান গাইতে পারবে না কিন্তু গান গাইতে পারবে","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْغِنَى عَنْ كَثْرَةِ ‏ ‏الْعَرَضِ ‏ ‏وَلَكِنَّ الْغِنَى غِنَى النَّفْسِ ‏","","",""],[8702,8702,"","আমরা আমার বাবার পেপার চুরি করার চেষ্টা করেছি। এটা বাড়িতে ছিল, ছবি বা কুকুর।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي جِئْتُ الْبَارِحَةَ فَلَمْ يَمْنَعْنِي أَنْ أَدْخُلَ عَلَيْكَ إِلَّا أَنَّهُ كَانَ فِي الْبَيْتِ صُورَةٌ أَوْ كَلْبٌ ‏","","",""],[8703,8703,"","আমরা কয়েক বছর আগে কথা বলেছিলাম, কিভাবে করতে হয় তা বলার চেষ্টা করছে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আপনার কাছ থেকে আত্মসমর্পণ করেছেন। তিনি বলেছিলেন, \"ঈশ্বর, তুমি বলেছিলে তুমি এমন কিছু না হতে পার না।\" মিষ্টি. সে তার হাত আত্মসমর্পণ করেছে তাকে চুমু দিবে আর সে তাকে সেলাই করবে.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ سِيرِينَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْكُمْ مِنْ أَحَدٍ يُدْخِلُهُ عَمَلُهُ الْجَنَّةَ وَلَا ‏ ‏يُنَجِّيهِ مِنْ النَّارِ إِلَّا بِرَحْمَةٍ مِنْ اللَّهِ وَفَضْلٍ قَالَ قَالُوا يَا رَسُولَ اللَّهِ وَلَا أَنْتَ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ مِنْهُ بِرَحْمَةٍ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ يَقْبِضُهَا وَيَبْسُطُهَا ‏","","",""],[8704,8704,"","আমরা সারাজীবন ধরে আমাদের উপর দৃঢ় আস্থা গড়ে তুলতে চেষ্টা করেছি, ঈশ্বর আমাদের নগর দরজা কাজ করেছেন, আপনার মন থেকে একজন যুবক বিশ্রাম নিচ্ছে এবং সে তার থেকে শোনা আর বলে যে, সে শুনতে পেয়েছে, যখন একজন মানুষ স্যুটে ঢুকে তার আত্মা মুছে ফেলেছে, সে ঈশ্বরকে তার গৌরব দিয়ে আঘাত করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ زَيْدٍ ‏ ‏عَمِّي ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَلَى بَابِ ‏ ‏الْمَدِينَةِ ‏ ‏فَمَرَّ شَابٌّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏كَأَنَّهُ مُسْتَرْخِي ‏ ‏الْإِزَارِ ‏ ‏قَالَ ارْفَعْ ‏ ‏إِزَارَكَ ‏ ‏فَجَعَلَ يَعْتَذِرُ فَقَالَ إِنَّهُ اسْتَرْخَى وَإِنَّهُ مِنْ كَتَّانٍ فَلَمَّا مَضَى قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي فِي ‏ ‏حُلَّةٍ ‏ ‏لَهُ مُعْجَبٌ بِنَفْسِهِ إِذْ خَسَفَ اللَّهُ بِهِ الْأَرْضَ فَهُوَ ‏ ‏يَتَجَلْجَلُ ‏ ‏فِيهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[8705,8705,"","আমরা কয়েক বছর আগে কথা বলেছিলাম, আমরা বাবার কাছে বাবার বন্য সাক্ষীর দিকে তাকিয়েছিলাম। শুধু তাকে সন্দেহ করা হয়েছে প্রার্থনা করা সুস্থ হয়ে উঠবে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏ذَوَّادٌ أَبُو الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏هَجَّرْتُ ‏ ‏إِلَّا وَجَدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ فَصَلَّى ثُمَّ قَالَ ‏ ‏اشِكَمَتْ ‏ ‏دَرْدْ ‏ ‏قَالَ قُلْتُ لَا قَالَ ‏ ‏قُمْ فَصَلِّ فَإِنَّ فِي الصَّلَاةِ شِفَاءً ‏","","",""],[8706,8706,"","আমরা আমার বাবা একজন ভালো মানুষ হওয়া সম্পর্কে কথা বলেছি যে তিনি বলতে চাচ্ছেন তিনি আমাকে পবিত্র শহর থেকে বের করে দিতে চান আর এটা ভালো হবে সপ্তম।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدَعَنَّ أَهْلُ ‏ ‏الْمَدِينَةِ ‏ ‏الْمَدِينَةَ ‏ ‏وَهِيَ خَيْرُ مَا يَكُونُ ‏ ‏مُرْطِبَةٌ ‏ ‏مُونِعَةٌ ‏ ‏فَقِيلَ مَنْ يَأْكُلُهَا قَالَ الطَّيْرُ وَالسِّبَاعُ ‏","","",""],[8707,8707,"","আমরা আমার ছেলে বাবার ব্যাপারে কথা বলেছি... ...আমার বাবাকে একজন উৎপীড়ক হিসেবে ভয় পেতে, ঈশ্বর তাকে শিখিয়েছেন আর সে আমার ক্ষমতা দিয়ে দেবে... ...আর তারা মানুষকে খুঁজে বের করবে। আমি ঈশ্বরকে বলতে শুনি, এটা চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ ‏ ‏صَدَقَةُ ‏ ‏قَوْمِي وَهُمْ أَشَدُّ النَّاسِ عَلَى ‏ ‏الدَّجَّالِ ‏ ‏يَعْنِي ‏ ‏بَنِي تَمِيمٍ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا كَانَ قَوْمٌ مِنْ الْأَحْيَاءِ أَبْغَضُ إِلَيَّ مِنْهُمْ فَأَحْبَبْتُهُمْ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا ‏","","",""],[8708,8708,"","আমার ভাই যখন জিনিয়াস ছিলেন, তখন আমরা গ্রীষ্মের কথা বলেছিলাম। ঈশ্বর তাকে আদেশ দিয়েছেন। আর আমরা তোমার অনুগ্রহের জন্য আত্মসমর্পণ করবো।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعِمَّا لِلْمَمْلُوكِ إِذَا أَدَّى حَقَّ اللَّهِ وَحَقَّ ‏ ‏مَوَالِيهِ ‏ ‏قَالَ ‏ ‏كَعْبٌ ‏ ‏صَدَقَ اللَّهُ وَرَسُولُهُ لَا حِسَابَ عَلَيْهِ وَلَا عَلَى مُؤْمِنٍ ‏ ‏مُزْهِدٍ ‏","","",""],[8709,8709,"","আমি আমার বাবার কথা বলেছিলাম আমার ভাই কুমারী হয়ে যাওয়ার কথা। খোদা তাদের কাছে সমর্পণ করতে হবে, আমি তাকে তার মৃত্যুর জন্য খুন করবো। আমরা যে জীবিতদের নিয়ে মজা করতে যাচ্ছি, সে কৌতুক করে বলে যাচ্ছি। আর ক্ষমা.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ فَإِنَّمَا أَنَا بَشَرٌ فَأَيُّمَا مُسْلِمٍ لَعَنْتُهُ أَوْ آذَيْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَقُرْبَةً ‏ ‏حَدَّثَنَاهُ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏أَنَّهُ قَالَ زَكَاةً وَرَحْمَةً ‏","","",""],[8710,8710,"","আমরা বাবার একটা ভালবাইর জন্য অনুসন্ধানের কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে এমন নয় যে তার হাত সব কিছুর সাথে বিশ্বাসঘাতকতা করতে ভুলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ أَبِي السَّمْحِ ‏ ‏عَنْ ‏ ‏ابْنِ حُجَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيَخْتَصِمَنَّ كُلُّ شَيْءٍ يَوْمَ الْقِيَامَةِ حَتَّى الشَّاتَانِ فِيمَا انْتَطَحَتَا ‏","","",""],[8711,8711,"","আমরা আমার বাবাকে একটা উৎপীড়ক বলতে বলেছিলাম, সে একটা গাছের থেকে চেষ্টা করবে... ...যেটা হয়তো আমাদের উপর আঘাত করেছে... ...যে ছায়ার রাতের অন্ধকারটা সবচেয়ে ভাল ডেবটের ভাগ্য একটু ঋণের মতো, ছোঁয়ার সময় তার কথোপকথন চকলেটের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ ‏ ‏فِتَنًا ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا يَبِيعُ قَوْمٌ دِينَهُمْ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا قَلِيلٍ الْمُتَمَسِّكُ يَوْمَئِذٍ بِدِينِهِ كَالْقَابِضِ عَلَى الْجَمْرِ ‏ ‏أَوْ قَالَ عَلَى الشَّوْكِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ خَبَطِ الشَّوْكَةِ ‏","","",""],[8712,8712,"","আমরা আমার বাবা, আমার ভাই, আমাদের জিজ্ঞেস করতে বলেছি, আমি তাদেরকে মই দিয়ে দেবো, যে তুমি আমার মাতাল হলে তাকে কখনোই জানিয়ে দেবে না। কাছাকাছি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَتَّخِذُ عِنْدَكَ ‏ ‏عَهْدًا ‏ ‏لَنْ ‏ ‏تُخْلِفَنِيهِ إِنَّمَا أَنَا بَشَرٌ فَأَيُّمَا عَبْدٍ جَلَدْتُهُ أَوْ شَتَمْتُهُ أَوْ سَبَبْتُهُ فَاجْعَلْهَا لَهُ صَلَاةً وَقُرْبَةً ‏","","",""],[8713,8713,"","আমরা আমার বাবাকে ভালো করে বলেছিলাম যে আমার বাবা একজন পলাতক... ...তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন... ...তিনি আত্মসমর্পণ করেছেন আর ঈশ্বর তাকে উদ্ধার করবেন. চুলটা যদি চুল না ধরে থাকে, তাহলে এটাকে চাঁদের রেকর্ডে রাখুন অথবা সেলাইয়ের কথা বলে দিন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏وَحَسَنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَبِ ‏ ‏مِنْ شَرٍّ قَدْ اقْتَرَبَ ‏ ‏فِتَنًا ‏ ‏كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا يَبِيعُ قَوْمٌ دِينَهُمْ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا قَلِيلٍ الْمُتَمَسِّكُ يَوْمَئِذٍ بِدِينِهِ كَالْقَابِضِ عَلَى الْجَمْرِ ‏ ‏أَوْ قَالَ عَلَى الشَّوْكِ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ خَبَطِ الشَّوْكِ ‏","","",""],[8714,8714,"","বাবা হাররির কথা বলেছিলাম, ঈশ্বর তাকে অনেক মই দিতে হবে, তারা বলেছে তারা মূল্যহীন। সে বলেছে, সে বলে বেনকে নিজের অধিকার হিসেবে দেখেছে। আর সে তাকে নিরাপদে রাখতে চেয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُكْثِرُونَ هُمْ الْأَقَلُّونَ يَوْمَ الْقِيَامَةِ إِلَّا مَنْ قَالَ بِالْمَالِ هَكَذَا وَهَكَذَا وَهَكَذَا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَقَلِيلٌ مَا هُمْ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏وَأَشَارَ بَيْنَ عَيْنَيْهِ وَعَنْ يَمِينِهِ وَعَنْ يَسَارِهِ وَمِنْ خَلْفِهِ ‏","","",""],[8715,8715,"","বেন মুসার সাথে কথা বলেছি আমরা বাবার ব্যাপারে কথা বলেছি, সে বলতেই হবে যে আমরা আমার ব্যাপারে ভাল ভাবে চিন্তা করেছি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي إِنْ ظَنَّ بِي خَيْرًا فَلَهُ وَإِنْ ظَنَّ شَرًّا فَلَهُ ‏","","",""],[8716,8716,"","আমরা যে কথাগুলো জয় করতে চেষ্টা করেছি, তা হল... ...বাবা হারাহর কাছে বলতে শুনেছি যে ঈশ্বরকে রক্ষা করার চেয়ে বরং ঈশ্বরের কাছে বেশি কিছু করার জন্য. আমার মত বাইরে গিয়ে, একটা ভূট্টা বা প্রেমের মধ্যে দিয়ে চলে গিয়ে একবার বলতে পারি প্রভু শুনছিলেন.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَمْروٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ أَرَادَ أَنْ يَخْلُقَ مِثْلَ خَلْقِي فَلْيَخْلُقْ ذَرَّةً أَوْ حَبَّةً ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏مَرَّةً سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَمَنْ ‏","","",""],[8717,8717,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমরা বাবার ছেলেকে ছেড়ে দিতে চাই। লর্ড প্রার্থনা করলেন আর তাকে আত্মসমর্পণ করতে হবে যদি আমি তার সব ত্যাগ করি।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ضَحَّى أَحَدُكُمْ فَلْيَأْكُلْ مِنْ أُضْحِيَّتِهِ ‏","","",""],[8718,8718,"","আমি বাবার মৃত্যুর বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ ‏ ‏مَعَادِنُ ‏ ‏خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا فِي الدِّينِ ‏","","",""],[8719,8719,"","আমরা বাবার বাবার থেকে তার বাবার ব্যাপারে একটা আরোগ্যকারীর কথা বলেছিলাম, সে ঐ দুই শব্দের তিনটা শব্দ ঘষতে শুরু করলো। আর অন্য দুইজন বলেছিল যে তুমি তিন বার। অর্ধ-বিস্তৃত ধ্বংসের অপরাধী।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏بَيَّاعِ الْمُلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏ثُلَّةٌ ‏ ‏مِنْ الْأَوَّلِينَ وَقَلِيلٌ مِنْ الْآخِرِينَ ‏} ‏شَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ فَنَزَلَتْ ‏ { ‏ثُلَّةٌ ‏ ‏مِنْ الْأَوَّلِينَ وَثُلَّةٌ مِنْ الْآخِرِينَ ‏} ‏فَقَالَ ‏ ‏أَنْتُمْ ثُلُثُ أَهْلِ الْجَنَّةِ بَلْ أَنْتُمْ نِصْفُ أَهْلِ الْجَنَّةِ وَتُقَاسِمُونَهُمْ النِّصْفَ الْبَاقِي ‏","","",""],[8720,8720,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং ঈশ্বর আমাকে সাহায্য করবেন বলে ঈশ্বর আমাকে বলেছিলেন । তোমার বাবা বলেছে যে তোমার মা বলেছে যে তোমার মা বলেছে যে তোমাকে বলেছে যে কে বলেছে যে তোমাকে বলেছে যে তোমাকে বলেছে যে তোমাকে বলেছে যে তোমাকে বলেছে যে তোমাকে বলেছে যে তোমাকে বলেছে. যে তোমার বাবা বলেছিলেন যে, সে বলেছে যে, সে তোমার বাবা।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏نَبِّئْنِي بِأَحَقِّ النَّاسِ مِنِّي صُحْبَةً فَقَالَ نَعَمْ وَاللَّهِ لَتُنَبَّأَنَّ قَالَ مَنْ قَالَ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أُمُّكَ قَالَ ثُمَّ مَنْ قَالَ ثُمَّ أَبُوكَ ‏","","",""],[8721,8721,"","আমরা বাবার সাথে ঝামেলার কথা বলেছিলাম, আমাকে সাহায্য করার চেষ্টা করবে। সে বলল আমি আমার নিজের মতো সৃজনশীল হতে নিজেকে বাঁচিয়ে রাখতে চাই, তারা আমার নিজের আর ভালোবাসার মতো।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَ الْحَدِيثَ قَالَ ‏ ‏وَمَنْ أَظْلَمُ مِمَّنْ خَلَقَ خَلْقًا كَخَلْقِي فَلْيَخْلُقُوا مِثْلَ خَلْقِي ذَرَّةً أَوْ ذُبَابَةً أَوْ حَبَّةً ‏","","",""],[8722,8722,"","আমরা একটি ভাল ছেলে সম্পর্কে কথা বলেছি যার মানে আমার বাবার একটি স্বপ্ন আছে। ঈশ্বর দাবি করেছেন যে, আমার মনে হয় সবকিছু ভুল। আমার মা আমার মা বাবা যে প্রার্থনা করেছিলেন, তা ফিরিয়ে দেওয়া","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَيْرٍ يَعْنِي عَبْدَ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ عَلَى الْمِنْبَرِ ‏ ‏أَشْعَرُ بَيْتٍ قَالَتْهُ ‏ ‏الْعَرَبُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏ ‏وَكَادَ ‏ ‏أُمَيَّةُ بْنُ أَبِي الصَّلْتِ ‏ ‏أَنْ يُسْلِمَ ‏","","",""],[8723,8723,"","আমরা বাবার সাথে কথা বলেছিলাম তার ভাইকে সাহায্য করার চেষ্টা করার কথা। যা করার করো, ভালো ছেলের সাথে কথা বলো।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَرْفَعُهُ قَالَ ‏ ‏لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا وَلَا تُؤْمِنُونَ حَتَّى تَحَابُّوا أَلَا أَدُلُّكُمْ عَلَى رَأْسِ ذَلِكَ ‏ ‏أَوْ مِلَاكِ ذَلِكَ ‏ ‏أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ أَفْشُوا السَّلَامَ بَيْنَكُمْ ‏ ‏و حَدَّثَنَاه ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏مَعْنَاهُ ‏","","",""],[8724,8724,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম যে, তিনি কখনো তা করবেন না । শোক.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ أَحَدِكُمْ قَيْحًا ‏ ‏يَرِيهِ خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[8725,8725,"","আমরা আমার বাবার কথা বলেছিলাম তার জন্য প্রার্থনা করার কথা। সে ছেড়ে দেবে কে ঈশ্বরের পথে কথা বলবে আর আল্লাহ জানে যে সে তার পথে পালিয়ে যাবে। জীবিত.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِ اللَّهِ وَاللَّهُ أَعْلَمُ بِمَنْ ‏ ‏يُكْلَمُ ‏ ‏فِي سَبِيلِهِ يَأْتِي الْجُرْحُ لَوْنُهُ لَوْنُ دَمٍ وَرِيحُهُ رِيحُ الْمِسْكِ ‏","","",""],[8726,8726,"","আমরা আমার বাবা তাকে তার ক্ষতির জন্য বড় করার চেষ্টা করে, এই চমক কিনে তার পথে চলে যায় এবং তার পথে এই সমস্ত কৌশলটি কিনে নিয়ে যায় এবং তারা তার কাছ থেকে টাকা কিনে নেয়।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ ‏ ‏نَهَى عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَهُوَ اشْتِرَاءُ الزَّرْعِ وَهُوَ فِي سُنْبُلِهِ ‏ ‏بِالْحِنْطَةِ ‏ ‏وَنَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَهُوَ شِرَاءُ الثِّمَارِ بِالتَّمْرِ ‏","","",""],[8727,8727,"","আমি আমার বাবার সঙ্গে কথা বলেছিলাম, তাকে জয় করার জন্য একটা পাতা তৈরি করার চেষ্টা করছি ।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ ‏","","",""],[8728,8728,"","আমরা আমার বাবাকে মুক্ত করার ব্যাপারে একটি পরিবার খুঁজে বের করার কথা বলেছিলাম। ঈশ্বর তাকে জিজ্ঞেস করেছেন এবং বললেন মানুষ আসছে এবং হয়তো সে বলেছে যে ক্রেতারা মানুষ খেঁজে বের করছে। তাদের নিজস্ব পথে.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبْعَثُ النَّاسُ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏شَرِيكٌ ‏ ‏يُحْشَرُ النَّاسُ ‏ ‏عَلَى نِيَّاتِهِمْ ‏","","",""],[8729,8729,"","আমরা আমার ভাইয়ের ইচ্ছা ব্যাখ্যা করে একটা নির্দিষ্ট ছেলেকে কথা বলেছি, ঈশ্বর আদেশ দিয়েছেন তাকে হত্যা করতে। আর তিনি তাকে আত্মসমর্পণ করবেন যে আমি আমার বন্দী। আমার প্রভু ছিল, জীবিত এবং রহস্য গোপন থাকলে সে নিজের আত্মা গান গাইতে পারত। তারপর এটা ঈশ্বরের আঙ্গুলের উপর আঘাত এবং বলে, এটা আমার সম্মান নিয়ে আসে। তিনি বলেছিলেন, তিনি যদি ঈশ্বরকে হত্যা করতে চান, তাহলে তাকে জিজ্ঞেস করব যে, তিনি জয়ী হয়েছেন কি না ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏كَانُوا يَغْتَسِلُونَ عُرَاةً وَكَانَ نَبِيُّ اللَّهِ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِنْهُ الْحَيَاءُ وَالسِّتْرُ وَكَانَ يَسْتَتِرُ إِذَا اغْتَسَلَ فَطَعَنُوا فِيهِ بِعَوْرَةٍ قَالَ فَبَيْنَمَا نَبِيُّ اللَّهِ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يَغْتَسِلُ يَوْمًا وَضَعَ ثِيَابَهُ عَلَى صَخْرَةٍ فَانْطَلَقَتْ الصَّخْرَةُ بِثِيَابِهِ فَاتَّبَعَهَا نَبِيُّ اللَّهِ ضَرْبًا بِعَصَاهُ وَهُوَ يَقُولُ ثَوْبِي يَا حَجَرُ ثَوْبِي يَا حَجَرُ حَتَّى انْتَهَى بِهِ إِلَى مَلَإٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَتَوَسَّطَهُمْ فَقَامَتْ وَأَخَذَ نَبِيُّ اللَّهِ ثِيَابَهُ فَنَظَرُوا فَإِذَا أَحْسَنُ النَّاسِ خَلْقًا وَأَعْدَلُهُمْ صُورَةً فَقَالَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏أَفَّاكِي ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَكَانَتْ بَرَاءَتُهُ الَّتِي بَرَّأَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا ‏","","",""],[8730,8730,"","আমরা বাবার ব্যাপারে কথা বলেছি, তার দিকে তাকিয়েই ঈশ্বর তাকে দাবি করেছেন আর তিনি আত্মসমর্পণ করেছেন তার ভাইয়ের গাছ থেকে তিন সেকেন্ড দূরে না উড়িয়ে না দিতে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَأَحْسِبُهُ ذَكَرَهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا هِجْرَةَ فَوْقَ ثَلَاثٍ فَمَنْ هَجَرَ أَخَاهُ فَوْقَ ثَلَاثٍ فَمَاتَ دَخَلَ النَّارَ ‏","","",""],[8731,8731,"","আমরা দু'বছর আগে ঈশ্বরের লর্ডের কাছে বাবার চাইতে ভাল ছিলাম... ...অথবা ভগবানের কাছে প্রার্থনা করে... ...আর তার জন্মের আগ পর্যন্ত সে কাপুরুষের কাছে মাথা নত করতে পারত না।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَرْقُدَنَّ جُنُبًا حَتَّى تَتَوَضَّأَ ‏","","",""],[8732,8732,"","আমরা আমার বাবার ভাইয়ের শান্তি নিয়ে একটা কথা বলেছি। আপনি আমার নাম ধরে বলুন।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[8733,8733,"","আমরা আমার বাবার ইগো নিয়ে একটা স্বপ্ন নিয়ে কথা বলেছি। আমি কসম করে বলছি, তুমি তোমার বন্ধুদের খুঁজে বের করতে পারবে। আমি তোমাকে ঈশ্বর বলে দিবো না আর আমি এই পতনের হাত থেকে বাঁচাব। তুমি বলতে চাচ্ছ আমরা তাকে খুঁজে বের করব, সে তর্ক করেছিল মূসা তাদের সেল্মের সাথে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقِيَ ‏ ‏آدَمَ ‏ ‏مُوسَى ‏ ‏فَقَالَ أَنْتَ ‏ ‏آدَمُ ‏ ‏الَّذِي خَلَقَكَ اللَّهُ بِيَدِهِ وَأَسْكَنَكَ جَنَّتَهُ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ ثُمَّ صَنَعْتَ مَا صَنَعْتَ فَقَالَ ‏ ‏آدَمُ ‏ ‏لِمُوسَى ‏ ‏أَنْتَ الَّذِي كَلَّمَكَ اللَّهُ وَأَنْزَلَ عَلَيْكَ التَّوْرَاةَ قَالَ نَعَمْ قَالَ فَهَلْ تَجِدُهُ مَكْتُوبًا عَلَيَّ قَبْلَ أَنْ أُخْلَقَ قَالَ نَعَمْ قَالَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[8734,8734,"","আমরা আমার বাবার সবচেয়ে ভাল ভাই, তার বেঁচে থাকার চেয়ে বেশি শান্তি পাবে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏دَاوُدَ أَبِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْثَرُ مَا ‏ ‏يَلِجُ ‏ ‏بِهِ الْإِنْسَانُ النَّارَ الْأَجْوَفَانِ الْفَمُ وَالْفَرْجُ وَأَكْثَرُ مَا ‏ ‏يَلِجُ ‏ ‏بِهِ الْإِنْسَانُ الْجَنَّةَ تَقْوَى اللَّهِ عَزَّ وَجَلَّ وَحُسْنُ الْخُلُقِ ‏","","",""],[8735,8735,"","বাবা আমাকে খুন করার চেষ্টা করছে, কিন্তু বাবা চুপ আছে এমন লোকদের আশীর্বাদ তো আর পাওয়া যাবে না। আর সে তার চূড়ান্ত বিদায় দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمَسْتُورُ يَعْنِي ابْنَ أَبِي عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ الْمَخْزُومِيُّ ‏ ‏قَالَ ‏ ‏لَقِيَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَجُلٌ وَهُوَ يَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْتَ ‏ ‏نَهَيْتَ النَّاسَ عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ قَالَ لَا وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏وَلَكِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[8736,8736,"","আমি আমার ছেলের সবচেয়ে ভাল অবস্থা নিয়ে কথা বলেছি। আমি যুবক যে আমার বাবা বলেছেন, সে একজন লোক যে প্রভুর জয় করেছে। তিন দিনের আগে, তিন দিনের আগে। প্রতি মাসে এবং বিমূর্ততা ত্যাগ করে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ الْمُخْتَارِ الْأَنْصَارِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ فَيْرُوزَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو رَافِعٍ الصَّائِغُ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏ثَلَاثَةٌ حَفِظْتُهُنَّ عَنْ خَلِيلِي ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَتْرُ ‏ ‏قَبْلَ النَّوْمِ وَصَوْمُ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَرَكْعَتَيْ الضُّحَى ‏","","",""],[8737,8737,"","আমাদের বাবা-মা'কে বলা হয়েছে, আমরা যখন নিজের রক্ত বাঁচাতে কয়েকদিন সময় কাটাই, তখন আমরা সবাই আমাদের বাবাকে কিছু দিন ধরে না, আমার হিংসার বীজের বাচ্চাটিকে উপহাস করার স্বপ্ন দেখি। লর্ড তার জন্য প্রার্থনা করেন এবং তিনি আত্মসমর্পণ করেন যে তিনি লেকের শিকারী সঙ্গে এসেছিলেন তিনি বলেন তিনি কখনো তার নিজের মানুষ হবেন না. আমরা এখন বেড়ে যাচ্ছি, আমরা পানি নিয়ে কাজ করছি, তিনি তার বাবার সঙ্গে যেভাবে আচরণ করেছিলেন, তা থেকে আমরা কী শিখতে পারি?","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏مَوْلَى ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَلَمَةَ بْنِ الْأَزْرَقِ الْمَخْزُومِيِّ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏ ‏أَحَدِ ‏ ‏بَنِي عَبْدِ الدَّارِ بْنِ قُصَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ جَاءَهُ نَاسٌ صَيَّادُونَ فِي الْبَحْرِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا أَهْلُ ‏ ‏أَرْمَاثٍ ‏ ‏وَإِنَّا نَتَزَوَّدُ مَاءً يَسِيرًا إِنْ شَرِبْنَا مِنْهُ لَمْ يَكُنْ فِيهِ مَا نَتَوَضَّأُ بِهِ وَإِنْ تَوَضَّأْنَا ‏ ‏لَمْ يَكُنْ فِيهِ مَا نَشْرَبُ ‏ ‏أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ فَهُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ ‏","","",""],[8738,8738,"","আমরা আমার বাবার ছেলেকে নিয়ে কথা বলেছি, যদি তুমি তোমার সমবেদনার কথা বলো আর পাপ করে থাকো...","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ وَالْإِمَامُ يَخْطُبُ أَنْصِتْ فَقَدْ ‏ ‏لَغَوْتَ ‏","","",""],[8739,8739,"","আমরা বাবার ছেলের ব্যাপারে কথা বলেছি বাবার বাবার স্বপ্নের জন্য আমার বিয়ে নিয়ে। ঈশ্বর আপনার সব মানুষকে দিতেন এবং তার আত্মার রাজা হবেন। ♪♪ এটা আনা উচিত ছিল ♪♪","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ وَيُمَجِّسَانِهِ كَمَثَلِ الْبَهِيمَةِ ‏ ‏تُنْتِجُ ‏ ‏الْبَهِيمَةَ هَلْ تَكُونُ فِيهَا ‏ ‏جَدْعَاءُ ‏","","",""],[8740,8740,"","আমরা আমার বাবার ছেলেকে দিয়ে আমার বাবার ছেলেকে দেওয়ার ব্যাপারে কথা বলেছি। নবী ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং যে খারাপ ছেলের জন্য সে প্রার্থনা করতো। ঈশ্বর কে হত্যা করেছে, আমি জানতাম তারা কি করেছে.","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ فَقَالَ اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ ‏","","",""],[8741,8741,"","আমার বাবার ছেলে-মেয়ের কথা বলেছিলাম, যদি আমার বাবা তার বাবা জন্ম দিতে চায়, তাহলে তারা ভয় পেত, যদি আমার চেয়ে বড় আর ছোট থাকে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَمَمْتُمْ النَّاسَ فَخَفِّفُوا فَإِنَّ فِيهِمْ الْكَبِيرَ وَالضَّعِيفَ وَالصَّغِيرَ ‏ ‏وَقَالَ ‏ ‏فِي حَدِيثٍ آخَرَ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ عَمْرِو بْنِ خِدَاشٍ ‏","","",""],[8742,8742,"","আমরা আমার বাবার ছেলে ঈশ্বরের প্রতি প্রেম থেকে দূরে চলে যাওয়ার ব্যাপারে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বলেছেন যে নরকের তাপ তারা চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏وَعَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ ‏","","",""],[8743,8743,"","আমরা দুজন ডাক্তারকে কথা বলেছি, আমার বাবার ছেলে সম্পর্কে স্বপ্ন দেখে। লর্ডের একজন লোক তার জন্য প্রার্থনা করে, আর সে তার নিজের কোন যাজককে ছেড়ে দিবে না নাকি আমি তাকে মেরে ফেলব। ঈশ্বর তোমার জন্য কিছু করবেন.","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ لِرَجُلٍ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِنٌّ ‏ ‏مِنْ الْإِبِلِ فَجَاءَهُ ‏ ‏يَتَقَاضَاهُ ‏ ‏فَطَلَبُوا لَهُ فَلَمْ يَجِدُوا إِلَّا ‏ ‏سِنًّا ‏ ‏فَوْقَ ‏ ‏سِنِّهِ ‏ ‏فَقَالَ أَعْطُوهُ فَقَالَ أَوْفَيْتَنِي ‏ ‏أَوْفَى ‏ ‏اللَّهُ لَكَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خِيَارَكُمْ أَحْسَنُكُمْ ‏ ‏قَضَاءً ‏","","",""],[8744,8744,"","আমরা বাবার সবচেয়ে ভালো ছেলের কথা বলেছিলাম, আল্লাহ আছে আর তিনি বলবেন যদি তিনি তার মানুষ আর তার কোমরের মধ্যে বসেন... ...তাহলে সে হারিয়ে যাবে আর তাকে ধোবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏شُعَبِهَا ‏ ‏الْأَرْبَعِ ثُمَّ ‏ ‏جَهَدَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[8745,8745,"","তিনি বলেন যে, ঈশ্বর আমার মাকে এমন কিছু করতে দিয়েছেন, যা কখনো ভুলে যায়নি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ تَجَاوَزَ لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تُكَلِّمْ بِهِ أَوْ تَعْمَلْ بِهِ ‏","","",""],[8746,8746,"","আমরা আমার বাবার কথা বলেছিলাম আমার ভাই একজন উৎপীড়ক, তাকে আত্মসমর্পণ করতে হবে রাগ করতে না, না দৌড়ান না, প্রতিযোগিতা করা আর ঈশ্বরের দাস হওয়া।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ نَبْهَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَنَافَسُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[8747,8747,"","আপনার চাচার কথা বলেছিলাম আমার বাবার বিদ্রোহ নিয়ে কথা বলতে। লর্ড তার কাছে প্রার্থনা করে বললেন, আমি বিশ্বাস করি তার ভালো শব্দ বা অন্য কিছু। আমার মা আমার বাবা। আমি মনে করি, আমি মনে করি, আমার বাবা। আমি আমার বাবা, আমি তাকে বলেছিলাম, আমি আমার বাবার সাথে কথা বলতে চাই। আমি আমার বাবার সাথে কথা বলতে চাই। আমি তাকে বলি। আমি যখন আমি বলেছিলাম, আমি আমার বাবার সাথে কথা বলতে চাই, আমি আমার বাবা আমার বাবা আমাদের সাথে কথা বলতে চাই। আর আমি তাকে আমি মনে করি। আমি আমার বাবা আমার বাবা, আমি মনে করি। আমি মনে করি, আমি জানি না যে, আমি তাকে আমি জানি না যে, আমি সবসময় তোমার সাথে কথা বলতে চাই। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি তোমার সাথে নেই। আমি আমার বাবা। আমি জানি, আমি জানি, আমি জানি, আমি তোমার মা, আমি তোমার মা, আমি তোমার মা, আমি আমার বাবা। প্রার্থনা করা","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَصْدَقُ كَلِمَةٍ قَالَهَا الشَّاعِرُ ‏ ‏أَلَا كُلُّ شَيْءٍ مَا ‏ ‏خَلَا ‏ ‏اللَّهَ بَاطِلُ ‏ ‏وَكَادَ ‏ ‏أُمَيَّةُ بْنُ أَبِي الصَّلْتِ ‏ ‏أَنْ يُسْلِمَ ‏","","",""],[8748,8748,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে আমরা বাবার সাথে কথা বলেছি যে তাকে বলতেই হবে যে সে-ই হবে যে হতে হবে। যে একজন সেই ব্যাক্তি হতে হবে যার কাছে সে হবে সেই হতে হবে, যে কিনা হতে হবে সেই ব্যক্তি, যে কিনা হতে হবে। কে বলতে হবে, আমি হাল ছেড়ে দেব না যে তুমি খেতে চাও বা খেয়ে খেতে চাও, তাকে দেওয়া যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ الْأُكْلَةُ وَالْأُكْلَتَانِ أَوْ التَّمْرَةُ وَالتَّمْرَتَانِ وَلَكِنْ الْمِسْكِينُ الَّذِي لَا يَسْأَلُ شَيْئًا وَلَا يُفْطَنُ بِمَكَانِهِ ‏ ‏فَيُعْطَى ‏","","",""],[8749,8749,"","আমরা আমার বাবার সাথে কথা বলেছিলাম যে আমরা বাবার সাথে কথা বলেছি যে তাকে বলতেই হবে যে সে-ই হবে যে হতে হবে। যে একজন সেই ব্যাক্তি হতে হবে যার কাছে সে হবে সেই হতে হবে, যে কিনা হতে হবে সেই ব্যক্তি, যে কিনা হতে হবে। আর সে বলবে যে ঈশ্বর হচ্ছেন আমার কাছে সব আকাশের সব কিছুর সমাধান আর আমি তার গেরিলা আমি তার হরিণ আর তার প্রেমিকদের বলে থাকি আমার আনন্দের। ঈশ্বরের আত্মা পরাজিত হয় এবং তাকে বলা হয়.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ يَدَعُ طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي فَالصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَلَخُلُوفُ ‏ ‏فِيهِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[8750,8750,"","আমরা আমার বাবার সঙ্গে কথা বলেছিলাম, মাখনের মতো আমরা আমার বাবার সঙ্গে কথা বলেছিলাম । তার হাত।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ نِسَاءٍ رَكِبْنَ الْإِبِلَ نِسَاءُ ‏ ‏قُرَيْشٍ ‏ ‏أَحْنَاهُ عَلَى وَلَدٍ وَأَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ ‏","","",""],[8751,8751,"","বাবা'র কথা বলেছিলাম আমরা আমার বাবার কাছে ফাঁস করে দেব, যে আমার বাবাকে ফাঁস করে দেবে। আমি বলতে চাই, ঈশ্বর প্রিয় এবং আমি যদি সন্তান হতাম যে আমি আমার ছেলে হত, তা হলে সে আমাকে মিথ্যা বলবে। তাকে বলবে যে আমার ছেলে আছে... ...নাকি তুমি আমার মত প্রস্তুত থাকবে না.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ ذَكْوَانَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏يَشْتُمُنِي ابْنُ ‏ ‏آدَمَ ‏ ‏وَمَا يَنْبَغِي لَهُ أَنْ يَشْتُمَنِي وَيُكَذِّبُنِي وَمَا يَنْبَغِي لَهُ أَنْ يُكَذِّبَنِي أَمَّا شَتْمُهُ إِيَّايَ قَوْلُهُ إِنَّ لِي وَلَدًا وَأَمَّا تَكْذِيبُهُ إِيَّايَ قَوْلُهُ لَنْ يُعِيدَنِي كَمَا بَدَأَنِي ‏","","",""],[8752,8752,"","বাবা যখন মারা যান, তখন আমরা বাবার সঙ্গে চিৎকার করে বলেছিলাম যে, তিনি যেন তার কাছে প্রার্থনা করেন এবং জলে তার রক্ত ফেলে না দেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُبَالُ فِي الْمَاءِ الَّذِي لَا يَجْرِي ثُمَّ يُغْتَسَلُ مِنْهُ ‏","","",""],[8753,8753,"","আমরা আমার বাবার সাথে আমার ছেলের সাথে যাওয়ার চেষ্টা নিয়ে কথা বলেছি, সে বলবে না আমি কথা দিচ্ছি, ফুল ভয়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولُ أَحَدُكُمْ يَا ‏ ‏خَيْبَةَ ‏ ‏الدَّهْرِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ هُوَ الدَّهْرُ ‏","","",""],[8754,8754,"","বাবার সাথে কথা বলেছি, নাকি বাবার ভালোবাসা নিয়ে কথা বলতে চেষ্টা করেছি, ঈশ্বরের ইচ্ছা ছিল তার নিজের শান্তি আর শান্তি তার নিজের পাপের পিতা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ نَبِيٌّ مِنْ الْأَنْبِيَاءِ ‏ ‏يَخُطُّ ‏ ‏فَمَنْ وَافَقَ عِلْمَهُ فَهُوَ عِلْمُهُ ‏","","",""],[8755,8755,"","তিনি বলেছিলেন যে, তিনি তার জন্য প্রার্থনা করেছিলেন এবং জিজ্ঞেস করেছিলেন যে, সেই ভ্রমণটা ছিল এক বিরাট রহস্য এবং সেই সম্বন্ধে এক রহস্য । আক্রমণকারী ভয় পেয়ে যান।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ فُرَافِصَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُؤْمِنَ ‏ ‏غِرٌّ ‏ ‏كَرِيمٌ وَإِنَّ الْفَاجِرَ ‏ ‏خَبٌّ ‏ ‏لَئِيمٌ ‏","","",""],[8756,8756,"","আমি আমার বাবার সঙ্গে অনেক ঘোড়া নিয়ে কথা বলেছিলাম । এবং অন্ধকার, যা ঘটেনি, তাকে রক্ষা করুন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا دَامَ فِي مَجْلِسِهِ يَنْتَظِرُ الصَّلَاةَ وَالْمَلَائِكَةُ يَقُولُونَ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏","","",""],[8757,8757,"","আমি আমার বাবার নিষ্ঠুরতার জন্য লর্ড বেনের সাথে কথা বলেছি। ঈশ্বর তাকে শিক্ষা দিয়েছেন এবং তুমি রাগ করবে না, সে কোন অমর মানুষ নয়। সে এমন এক বিষয় বিক্রি করে দিয়েছে যা তুমি কখনো বৃদ্ধদের থেকে মুক্তি পেতে পারবে না। মহিলা, তার পাশ হবার স্বাদ নিয়ে আর আমি তোমাকে তার ভাইয়ের কথা চিন্তা করতে বলি না, আর তার পাপ পরিকল্পনা না করা। তুমি কখনোই তার শেষ শেষ পর্যন্ত যেতে পারবে না, তাই তাকে জিততে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا لَا يَبِيعَنَّ حَاضِرٌ ‏ ‏لِبَادٍ ‏ ‏وَلَا ‏ ‏تَلَقَّوْا الرُّكْبَانَ ‏ ‏بِبَيْعٍ وَأَيُّمَا امْرِئٍ ‏ ‏ابْتَاعَ ‏ ‏شَاةً فَوَجَدَهَا ‏ ‏مُصَرَّاةً ‏ ‏فَلْيَرُدَّهَا وَلْيَرُدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ وَلَا ‏ ‏يَسُمْ ‏ ‏أَحَدُكُمْ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبْ عَلَى خِطْبَتِهِ وَلَا تَسْأَلْ الْمَرْأَةُ طَلَاقَ أُخْتِهَا ‏ ‏لِتَكْتَفِئَ ‏ ‏مَا فِي إِنَائِهَا فَإِنَّ رِزْقَهَا عَلَى اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[8758,8758,"","আমরা আমাদের পালনকর ্ তার আদেশ পালন করছি , তিনি বললেন , যিনি বিশ ্ বজগতের পালনকর ্ তা । তিনি বললেন আমি নেকড়ের মত এটা পড়েছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ ‏ ‏الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ ‏ ‏أَنْ يَنْزِلَ حَكَمًا قِسْطًا وَإِمَامًا عَدْلًا فَيَقْتُلَ الْخِنْزِيرَ وَيَكْسِرَ الصَّلِيبَ وَتَكُونَ الدَّعْوَةُ وَاحِدَةً فَأَقْرِئُوهُ ‏ ‏أَوْ أَقْرِئْهُ ‏ ‏السَّلَامَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُحَدِّثُهُ فَيُصَدِّقُنِي فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ أَقْرِئُوهُ مِنِّي السَّلَامَ ‏","","",""],[8759,8759,"","আমরা বাবা বা তোমার সাথে কথা বলেছি, ঈশ্বর একটা গানের চেহারার জন্য বন্ধুত্বের হাত বাড়িয়ে দেবেন আর তুমি প্রভুর সাথে কথা বলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْقِلٌ يَعْنِي ابْنَ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّدَقَةُ ‏ ‏عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[8760,8760,"","আমি আমার বাবাকে আমার বস বলে বাপ্তাইজিত হওয়ার বিষয়ে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَلْبُ الشَّيْخِ شَابٌّ عَلَى حُبِّ اثْنَتَيْنِ طُولِ الْحَيَاةِ وَكَثْرَةِ الْمَالِ ‏","","",""],[8761,8761,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার চাচা অথবা তার উত্তরাধিকারীর জন্য একজন নারীকে বিয়ে করার জন্য আত্মসমর্পণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تَتَزَوَّجَ الْمَرْأَةُ عَلَى عَمَّتِهَا أَوْ عَلَى خَالَتِهَا ‏","","",""],[8762,8762,"","আমার বাবা হলেন এমন এক উপহার, যা প্রতি বছর তাকে হারানোর অনুমতি দেওয়া হবে ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ جَهَنَّمَ اسْتَأْذَنَتْ رَبَّهَا فَنَفَّسَهَا فِي كُلِّ عَامٍ مَرَّتَيْنِ فَشِدَّةُ الْحَرِّ مِنْ حَرِّ جَهَنَّمَ وَشِدَّةُ الْبَرْدِ مِنْ ‏ ‏زَمْهَرِيرِهَا ‏","","",""],[8763,8763,"","আর তিনি বলেছিলেন আমার বাবা ঈশ্বরের অনুগ্রহের উপহার ছিল, ঈশ্বর এটা উদ্ধার করতে হবে যদি তারা তাদের শপথ থেকে মুক্তি পায়।","‏ ‏و قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏عَنْ الصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[8764,8764,"","আমার বাবার কুমারীত্ব নিয়ে আমরা কথা বলেছি, ঈশ্বর এই গুজবগুলো তুলে ধরেছেন।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُفْرَدَ يَوْمُ الْجُمُعَةِ بِصَوْمٍ ‏","","",""],[8765,8765,"","আমার বাবা একজন উৎপীড়ক ছিলেন, যিনি ঈশ্বরের কাছে ছিলেন । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ أَشْرَاطِ السَّاعَةِ أَنْ يُرَى رُعَاةُ الشَّاءِ رُءُوسَ النَّاسِ وَأَنْ يُرَى الْحُفَاةُ الْعُرَاةُ الْجُوَّعُ ‏ ‏يَتَبَارَوْنَ ‏ ‏فِي ‏ ‏الْبِنَاءِ ‏ ‏وَأَنْ تَلِدَ الْأَمَةُ ‏ ‏رَبَّهَا ‏ ‏أَوْ ‏ ‏رَبَّتَهَا ‏","","",""],[8766,8766,"","আমরা দাদা-দাদীর সাথে কিছু একটা করেছি... ...যে আমার বাবার সাথে পার্থক্য তৈরি করেছে, যে কিনা কখনো ভুল করতে পারে নি। এই দর্শন ঈশ্বরের মন্দের তৃতীয় ভাগ এবং সে তোমাকে দেখে ভয় পায়, সে এমন কিছু করে না, সে এটা কেটে ফেলে না আর সে যেতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرُّؤْيَا ثَلَاثَةٌ فَبُشْرَى مِنْ اللَّهِ وَحَدِيثُ النَّفْسِ وَتَخْوِيفٌ مِنْ الشَّيْطَانِ فَإِذَا رَأَى أَحَدُكُمْ رُؤْيَا تُعْجِبُهُ فَلْيَقُصَّهَا إِنْ شَاءَ وَإِذَا رَأَى شَيْئًا يَكْرَهُهُ فَلَا يَقُصَّهُ عَلَى أَحَدٍ وَلْيَقُمْ فَلْيُصَلِّ ‏","","",""],[8767,8767,"","আমরা লর্ডের এক বাবার কথা বলেছি, তার ধুলো থেকে সূর্য বের হওয়ার আগে, ঈশ্বরের আছে।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ ‏","","",""],[8768,8768,"","আমরা শুধু একজন নির্দিষ্ট বাবার কথা বলেছি যে শান্তির জন্য আবেদন করেছে, আমার নাম আমার মেয়ে না।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي ‏","","",""],[8769,8769,"","আমরা একটা হিরার কথা বলেছিলাম বাবা ছিল একজন ঘোড়া যে বলেছে খোদা এসেছে। আমি এই ব্যাপারে একটা জীবন্ত পথ অনুসরণ করছি, কিভাবে তারা তাদের ভাগ্যকে তাড়া করে তাদের ভাগ্যকে অনুসরণ করে আর অনুপ্রাণিত করার জন্য। তাদের.","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ أَتْبَاعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي هَذَا الشَّأْنِ كُفَّارُهُمْ أَتْبَاعٌ لِكُفَّارِهِمْ وَمُسْلِمُوهُمْ أَتْبَاعٌ لِمُسْلِمِيهِمْ ‏","","",""],[8770,8770,"","আমার ছেলের প্রতিটা কামড় আমার বন্ধু হয়ে উঠেছে ।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى كُلِّ عُضْوٍ مِنْ أَعْضَاءِ بَنِي ‏ ‏آدَمَ ‏ ‏صَدَقَةٌ ‏","","",""],[8771,8771,"","আমরা আমার বাবা ছিলেন একটি ষাঁড় যে তার মাথা পেয়েছিলাম এবং তিনি তার মাথা পেয়েছিলাম. আমি সব আপনি যান যে পথে যেতে ভুল. আমি মানুষ দিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَاللَّهِ ‏ ‏لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلًا فَيَنْطَلِقَ إِلَى هَذَا الْجَبَلِ فَيَحْتَطِبَ مِنْ الْحَطَبِ وَيَبِيعَهُ وَيَسْتَغْنِيَ بِهِ عَنْ النَّاسِ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ أَعْطَوْهُ أَوْ حَرَمُوهُ ‏","","",""],[8772,8772,"","আমরা একটা ঘোড়ার কথা বলেছিলাম যেটা ছিল নগ্ন অবস্থায় থাকা একটা কুকুরের ছেলে । আমি যখন প্রথম তাকে এভাবে দেখি না, প্রভু আমাকে এভাবে আর করতে দিবেন না, তবে আমি থরকে ফিরে যাব তারপর সে থরকে দিয়ে আমার ছেলে মারা যাবে, বেঁচে যাওয়া মানুষটি ভালবাসা, আমার মা, আমি তোমাকেও একই কাজ করতে দেবো। তুমি তোমার লর্ডকে মরতে বলবে। যে ছেলেটি মারা গিয়েছিল, সে অগ্নি ও ভালবাসায় মারা গিয়েছিল, নাকি সে তার জীবনের উৎস!","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ هُوَ ابْنُ عَمْرٍو الْهَجَرِيُّ ‏ ‏فِيمَا يَحْسَبُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا امْرَأَةٌ فِيمَنْ كَانَ قَبْلَكُمْ تُرْضِعُ ابْنًا لَهَا إِذْ مَرَّ بِهَا فَارِسٌ مُتَكَبِّرٌ عَلَيْهِ شَارَةٌ حَسَنَةٌ فَقَالَتْ الْمَرْأَةُ اللَّهُمَّ لَا تُمِتْ ابْنِي هَذَا حَتَّى أَرَاهُ مِثْلَ هَذَا الْفَارِسِ عَلَى مِثْلِ هَذَا الْفَرَسِ قَالَ فَتَرَكَ الصَّبِيُّ الثَّدْيَ ثُمَّ قَالَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَ هَذَا الْفَارِسِ قَالَ ثُمَّ عَادَ إِلَى الثَّدْيِ يَرْضَعُ ثُمَّ مَرُّوا بِجِيفَةٍ حَبَشِيَّةٍ ‏ ‏أَوْ زِنْجِيَّةٍ ‏ ‏تُجَرُّ فَقَالَتْ أُعِيذُ ابْنِي بِاللَّهِ أَنْ يَمُوتَ مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَتَرَكَ الثَّدْيَ وَقَالَ اللَّهُمَّ أَمِتْنِي مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَقَالَتْ أُمُّهُ يَا بُنَيَّ سَأَلْتُ رَبَّكَ أَنْ يَجْعَلَكَ مِثْلَ ذَلِكَ الْفَارِسِ فَقُلْتَ اللَّهُمَّ لَا تَجْعَلْنِي مِثْلَهُ وَسَأَلْتُ رَبَّكَ أَلَّا يُمِيتَكَ مِيتَةَ هَذِهِ الْحَبَشِيَّةِ ‏ ‏أَوْ الزِّنْجِيَّةِ ‏ ‏فَسَأَلْتَ رَبَّكَ أَنْ يُمِيتَكَ مِيتَتَهَا قَالَ فَقَالَ الصَّبِيُّ إِنَّكِ دَعَوْتِ رَبَّكِ أَنْ يَجْعَلَنِي مِثْلَ رَجُلٍ مِنْ أَهْلِ النَّارِ وَإِنَّ الْحَبَشِيَّةَ ‏ ‏أَوْ الزِّنْجِيَّةَ ‏ ‏كَانَ أَهْلُهَا يَسُبُّونَهَا وَيَضْرِبُونَهَا وَيَظْلِمُونَهَا فَتَقُولُ ‏ ‏حَسْبِيَ اللَّهُ ‏ ‏حَسْبِيَ اللَّهُ ‏","","",""],[8773,8773,"","ভাববাদীর কাছে প্রার্থনা করার চেয়ে তিনি আরও ভাল ছিলেন আর তিনি বলেছিলেন যে, তাদের মধ্যে একজন যদি কখনও না হতো, তা হলে তিনি হয়তো বলতেন যে, তিনি নিশ্চয়ই তা করতেন । আমি ঈশ্বরের নামে শপথ করে বলছি, আমি চুরি করেছি।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَامَ أَحَدُكُمْ يَوْمًا فَنَسِيَ فَأَكَلَ وَشَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏","","",""],[8774,8774,"","আমরা বাবার অর্থহীন আত্মার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, তুমি এখান থেকে যেতে চাও না, ঈশ্বরই একজন দৌড়।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏خِلَاسٍ ‏ ‏وَمُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسُبُّوا الدَّهْرَ فَإِنَّ اللَّهَ هُوَ الدَّهْرُ ‏","","",""],[8775,8775,"","আমরা আমার বাবার কাছে ঈশ্বরের দেবী হওয়ার কথা বলেছি। তিনি বলেছিলেন, আপনার প্রভু জিতে গেছেন এবং আমার প্রভু তাঁর ইচ্ছা পূরণ করেছেন। আমার নার্সদের জন্য এবং আমি তাকে ধরে নিচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفُ بْنُ أَبِي جَمِيلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ قَالَ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏عَبْدِي تَرَكَ شَهْوَتَهُ وَطَعَامَهُ وَشَرَابَهُ ‏ ‏ابْتِغَاءَ ‏ ‏مَرْضَاتِي وَالصَّوْمُ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[8776,8776,"","আমরা শুধু একজন বাবার কথা বলেছি যে তার শান্তির স্বপ্ন দেখেছে, আমি তোমাকে ঘুম থেকে জাগিয়ে তুলেছি, সে তার হাত তার হাতে রেখে দিতে পারে যতক্ষণ না সে তার হাত ধরে।","‏ ‏حَدَّثَنَا ‏ ‏هَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَأَرَادَ الطُّهُورَ فَلَا يَضَعَنَّ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[8777,8777,"","আমার খারাপ কাজের সবচেয়ে ভালো কথা বলেছি, বাবা একজন পলাতক... ...যে ঈশ্বরের কাছে প্রার্থনা করে... ...সে নিজেকে হার মানতে পারে নি।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنْبَأَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شَرِيكٌ يَعْنِي ابْنَ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْمِسْكِينُ الَّذِي تَرُدُّهُ التَّمْرَةُ أَوْ التَّمْرَتَانِ أَوْ اللُّقْمَةُ وَاللُّقْمَتَانِ إِنَّ الْمِسْكِينَ ‏ ‏الْمُتَعَفِّفُ ‏ ‏اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏لَا يَسْأَلُونَ النَّاسَ ‏ ‏إِلْحَافًا ‏ }","","",""],[8778,8778,"","আমরা বাবার আগুন দিয়ে যেতে চাই, আল্লাহ তা তুলে নিতে হবে আর আমাকে আনন্দ দিয়ে বরখাস্ত করা হবে। আমি আমাদের বাবার জীবনের মূল্য পূরণ করতে রাজি। তাকে আমার হাতে রাখা হয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُصِرْتُ ‏ ‏بِالرُّعْبِ ‏ ‏وَأُوتِيتُ ‏ ‏جَوَامِعَ الْكَلَامِ ‏ ‏وَبَيْنَمَا أَنَا نَائِمٌ أُوتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدِي ‏","","",""],[8779,8779,"","আমি আমার বাবার সাথে নরকে যাচ্ছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি আপনাকে নির্দোষদের মঙ্গলের কথা বলব না, ঈশ্বরের দয়ায় যা কিছু বলছিল, সব কিছুই ঈশ্বরের অনুগ্রহে। তাকে বলতে হবে না যে, মহারাজের প্রার্থনার উত্তর... ...এবং রানীকে সাহায্য করবে না যে তারা কতটা নির্দোষ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏أَبِي وَهْبٍ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالُوا بَلَى يَا رَسُولَ اللَّهِ قَالَ ‏ ‏رَجُلٌ آخِذٌ بِعِنَانِ فَرَسِهِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ كُلَّمَا كَانَتْ ‏ ‏هَيْعَةٌ ‏ ‏اسْتَوَى ‏ ‏عَلَيْهِ أَلَا أُخْبِرُكُمْ بِالَّذِي يَلِيهِ قَالُوا بَلَى قَالَ الرَّجُلُ فِي ‏ ‏ثُلَّةٍ ‏ ‏مِنْ غَنَمِهِ يُقِيمُ الصَّلَاةَ ‏ ‏وَيُؤْتِي الزَّكَاةَ أَلَا أُخْبِرُكُمْ بِشَرِّ ‏ ‏الْبَرِيَّةِ ‏ ‏قَالُوا بَلَى قَالَ الَّذِي يُسْأَلُ بِاللَّهِ وَلَا يُعْطِي بِهِ ‏","","",""],[8780,8780,"","আমি আমার বাবার সাথে কথা বলেছি যে বিয়ে আমার ভয় হচ্ছে। আমি একজন ভালো বাবা যে ঈশ্বরকে আমার সব ভবিষ্যদ্বাণীর জন্য করতে বলে। ভ্যালেন্টাইনের দিন আমার জন্য একটি প্রচারণা। মা।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةٌ وَأُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي لِيَوْمِ الْقِيَامَةِ شَفَاعَةً لِأُمَّتِي ‏","","",""],[8781,8781,"","আমরা আমার বিষে সাহায্য করার চেষ্টা করছিলাম, একটা ঘোড়া বললো ভগবান তার কাছে প্রার্থনা করুক আর ভগবানকে মেরে ফেলবে, প্রভুর অনুগ্রহ নিয়ে নাও।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[8782,8782,"","আমরা তাকে বলেছিলাম যে আমার বাবা জিততে চাচ্ছে আমি আমার বাবাকে একটা উপহার দিতে যাচ্ছি যে সে ঈশ্বরের কথা শুনেছে আর বলবে যে সে কে. আবারও আবারও তাকে বলতে শুরু করে যে, আমার বাবা তার ব্যথার চেয়ে একজন পলাতক ।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ هُرْمُزَ الْأَعْرَجَ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَأَلَ جَارَهُ أَنْ يَضَعَ خَشَبَةً فِي جِدَارِهِ فَلَا يَمْنَعْهُ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا لِي أَرَاكُمْ عَنْهَا مُعْرِضِينَ وَاللَّهِ لَأَرْمِيَنَّ بِهَا بَيْنَ أَكْتَافِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏وَأَبُو الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏مِثْلَهُ ‏","","",""],[8783,8783,"","আমি তার জন্য প্রার্থনা করতে শুনেছি এবং তাকে বলা হয়েছিল যে, তাকে যেতে এবং হত্যা করতে হবে । তুমি.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ وَالْإِمَامُ يَخْطُبُ فَقَدْ ‏ ‏لَغَوْتَ ‏","","",""],[8784,8784,"","বাবা তাকে বলেন যে, বাবা তাকে ছেড়ে চলে গেছেন আর তাকে জিজ্ঞেস করেছেন যে, ঈশ্বর তাকে উদ্ধার করেছেন । আমার লর্ডকে ফোন করতে না চাইলে, তার দরকার নেই।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏إِنَّ ‏ ‏أَبَا عُبَيْدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏يُسْتَجَابُ لِأَحَدِكُمْ مَا لَمْ يَعْجَلْ فَيَقُولُ قَدْ دَعَوْتُ رَبِّي فَلَمْ يَسْتَجِبْ لِي ‏","","",""],[8785,8785,"","আমার বাবার কথা আমার বাবার কাছে যে - উপহার ছিল, তা আমার বাবা বলেছিলেন, যিনি ঈশ্বরের কাছে তার শান্তির জন্য একটা উপহার পাঠিয়েছিলেন । ঈশ্বর ঈশ্বর ঈশ্বর ঈশ্বরকে হত্যা করেছেন, প্রভু ও পবিত্র পিতার পুত্র ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي عُبَيْدُ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏فِي صَلَاةِ الْفَجْرِ بَعْدَ الرُّكُوعِ فَقَالَ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏وَسَلَمَةَ بْنَ هِشَامٍ ‏ ‏وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏وَالْمُسْتَضْعَفِينَ مِنْ الْمُسْلِمِينَ وَالْمُسْلِمِينَ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ ‏ ‏فَوَافَقَهُ ‏ ‏الْقَاسِمُ ‏ ‏عَلَى ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ بَعْدَ الرُّكُوعِ ‏","","",""],[8786,8786,"","আমরা আমার বাবার গেম খেলার কথা বলেছিলাম যখন আমরা আমার ভাই বা না-এর কথা বলেছিলাম, ঈশ্বরের অনুগ্রহ নিজের জন্য করেছে এবং তিনি শুধু শান্তির জন্য তার ভয়কে বাড়িয়ে দেবেন। তোমার আত্মা.","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَضْلُ صَلَاةِ الْجَمَاعَةِ عَلَى صَلَاةِ أَحَدِكُمْ وَحْدَهُ خَمْسَةٌ وَعِشْرُونَ جُزْءًا ‏","","",""],[8787,8787,"","আমরা এমন একজনের কথা বলেছি যে আমার ভাই মুক্ত হওয়ার কথা বলেছে। ঈশ্বর বলতে হবে, তুমি রাতে এবং ঝড়ের নদীগুলো দেখতে এসেছ। আজ রাতে তুমি উঠে প্রমাণ করতে পারবে। রাতে তারা তোমাকে যেতে বলে আর বলবে তারা তোমাকে প্রার্থনা করতে দেবে। ঋণের দোষ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ تَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ وَالنَّهَارِ فِي صَلَاةِ الْفَجْرِ وَصَلَاةِ الْعَصْرِ قَالَ فَيَجْتَمِعُونَ فِي صَلَاةِ الْفَجْرِ قَالَ فَتَصْعَدُ مَلَائِكَةُ اللَّيْلِ وَتَثْبُتُ مَلَائِكَةُ النَّهَارِ قَالَ وَيَجْتَمِعُونَ فِي صَلَاةِ الْعَصْرِ قَالَ فَيَصْعَدُ مَلَائِكَةُ النَّهَارِ وَتَثْبُتُ مَلَائِكَةُ اللَّيْلِ قَالَ فَيَسْأَلُهُمْ رَبُّهُمْ ‏ ‏كَيْفَ تَرَكْتُمْ عِبَادِي قَالَ فَيَقُولُونَ أَتَيْنَاهُمْ وَهُمْ يُصَلُّونَ وَتَرَكْنَاهُمْ وَهُمْ يُصَلُّونَ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا قَدْ قَالَ فِيهِ ‏ ‏فَاغْفِرْ لَهُمْ يَوْمَ الدِّينِ ‏","","",""],[8788,8788,"","আমি তাদের বলেছিলাম যে, আমি তাদের সঙ্গে কথা বলেছি । তাদের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيُحِبُّ أَحَدُكُمْ إِذَا رَجَعَ إِلَى أَهْلِهِ أَنْ يَجِدَ ثَلَاثَ ‏ ‏خَلِفَاتٍ ‏ ‏عِظَامٍ سِمَانٍ قَالَ قُلْنَا نَعَمْ قَالَ ‏ ‏فَثَلَاثُ آيَاتٍ يَقْرَأُ بِهِنَّ فِي الصَّلَاةِ خَيْرٌ لَهُ مِنْهُنَّ ‏","","",""],[8789,8789,"","আমার বাবা আমার ছেলেকে লুকিয়ে রাখার চেষ্টা করছিল । আমার চেহারা, এবং আমার আত্মা হচ্ছে কারাগারের সৌজন্য। আমাদের মধ্যে সবচেয়ে ভালোটা হচ্ছে আমরা যে যুদ্ধ করেছি তা হচ্ছে, যখন আমরা কথা বলেছি, তখন আমাদের সম্মান আমার বাবার হয়ে যায়। আমার বাবার প্রতি তার প্রবল আগ্রহ আছে... ...তার কাছে... ...একজন পলাতক... ...আর একটা ঘোড়া... ...যে ঘোড়াটা বড় হয় নি, আর হারায় না।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ خُبَيْبٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْبَرِي عَلَى حَوْضِي وَإِنَّ مَا بَيْنَ مِنْبَرِي وَبَيْنَ بَيْتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَصَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا كَأَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏وَالْمِسْوَرِ بْنِ رِفَاعَةَ بْنِ أَبِي مَالِكٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏خُبَيْبٍ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏لَمْ يَزِدْ وَلَمْ يَنْقُصْ ‏","","",""],[8790,8790,"","আমি কতবার একটা সুখী গল্প শুনেছি, যা আমি একজন বাবাকে খুঁজে বের করতে চেয়েছিলাম। আমার বাবা যা বলেছিলেন, তা তাকে উদ্ধার করতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَيْسُورًا ‏ ‏مَوْلَى ‏ ‏قُرَيْشٍ ‏ ‏فِي حَلْقَةِ ‏ ‏سَعِيدٍ ‏ ‏يُحَدِّثُ ‏ ‏يَعْنِي ‏ ‏ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ مَرَّ بِهِ فَتًى يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏فَوَكَزَهُ ‏ ‏بِحَدِيدَةٍ كَانَتْ مَعَهُ ثُمَّ قَالَ أَلَمْ يَبْلُغْكَ مَا قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى الَّذِي يَجُرُّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[8791,8791,"","আমার বাবা একজন পলাতক, যিনি প্রভুর সঙ্গে কথা বলতে ও বলতে এসেছিলেন, ঈশ্বর আমাকে ভালোবাসেন । তার সাথে কথা বল.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ الضَّبِّيُّ الْأَحْوَصُ بْنُ جَوَّابٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ زُرَيْقٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أُحَدِّثُ نَفْسِي بِالْحَدِيثِ لَأَنْ أَخِرَّ مِنْ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَتَكَلَّمَ بِهِ قَالَ ذَلِكَ ‏ ‏صَرِيحُ ‏ ‏الْإِيمَانِ ‏","","",""],[8792,8792,"","আমাদের বাবা ঈশ্বরকে জানেন কি করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ زُرَيْقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏خَبَّبَ ‏ ‏خَادِمًا عَلَى أَهْلِهَا فَلَيْسَ مِنَّا وَمَنْ أَفْسَدَ امْرَأَةً عَلَى زَوْجِهَا فَلَيْسَ هُوَ مِنَّا ‏","","",""],[8793,8793,"","আমরা আমার বাবাকে সাহায্য করার চেয়ে ভালো কিছু করার চেষ্টা করেছি, একটি উপহার যা ঈশ্বর তার কাছে প্রার্থনা করেছিলেন এবং আমাকে সাম এবং আমি যদি স্যাম এবং আমি যেতে পারি তাহলে তাকে তিন বার আত্মসমর্পণ করতে হবে তিনি মিথ্যা বলেছিলেন এবং তারপর দোকানে ফিরে যান, তারপর তিনি খানে বিশ্বাস করতেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ فِي الْمُنَافِقِ وَإِنْ صَلَّى وَإِنْ صَامَ وَزَعَمَ أَنَّهُ مُسْلِمٌ إِذَا حَدَّثَ كَذَبَ وَإِذَا وَعَدَ أَخْلَفَ وَإِذَا ‏ ‏ائْتُمِنَ خَانَ ‏","","",""],[8794,8794,"","তিনি বলেন যে, তিনি স্বর্গে যাওয়ার আগে ঈশ্বর তাঁর কাছে তাঁর উপাসনার জন্য তাঁর কাছে যে - বইগুলো দিয়েছেন, সেগুলো তিনি পেয়েছেন । আমার রাগ হচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ كَتَبَ كِتَابًا بِيَدِهِ لِنَفْسِهِ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ فَوَضَعَهُ تَحْتَ عَرْشِهِ فِيهِ ‏ ‏رَحْمَتِي سَبَقَتْ غَضَبِي ‏","","",""],[8795,8795,"","আমাদের সাহায্য করার কথা ছিল তাকে চেষ্টা করতে সাহায্য করার ব্যাপারে। তাদের প্রতিবেশীরা আমাকে কয়েকবার কিছু বলে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ دَعَا إِلَى ‏ ‏هُدًى ‏ ‏كَانَ لَهُ مِنْ الْأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لَا يُنْقِصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنْ الْإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لَا يُنْقِصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا ‏","","",""],[8796,8796,"","আমরা আমার বাবা-মাকে আমার বাল কথা বলতে বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তাকে আত্মসমর্পণ করবেন তার বিশ্বাসের মিথ্যা কথা বলা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْبِرُ عَلَى ‏ ‏لَأْوَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏وَشِدَّتِهَا أَحَدٌ إِلَّا كُنْتُ لَهُ شَفِيعًا يَوْمَ الْقِيَامَةِ ‏ ‏أَوْ شَهِيدًا ‏","","",""],[8797,8797,"","আর এই আহ্বান ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন যে, তিনি শয়তানের কথা বলার জন্য শয়তানের সঙ্গে কথা বলেছিলেন ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ التَّثَاؤُبَ مِنْ الشَّيْطَانِ فَإِذَا تَثَاءَبَ أَحَدُكُمْ ‏ ‏فَلْيَكْظِمْ ‏ ‏مَا اسْتَطَاعَ ‏","","",""],[8798,8798,"","( গীতসংহিতা ৩৪: ৬) আর এই প্রার্থনা ঈশ্বরের কাছে করা হয় যেন তিনি তাঁকে উদ্ধার করেন এবং তিনি সেই দিনের জন্য যথেষ্ট যুদ্ধ শুনতে না পান ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْتَمِعُ كَافِرٌ وَقَاتِلُهُ فِي النَّارِ أَبَدًا ‏","","",""],[8799,8799,"","আর এই আহ্বানের মাধ্যমে ভাববাদী তার কাছে প্রার্থনা করেছেন আর তিনি যদি জানেন তার জন্য সবচেয়ে ভাল কিছু সে এটা দিয়ে দিয়েছে। সে তার মেয়ের কথা শুনেছে। একজনও ঈশ্বরকে ছেড়ে চলে যেতে শিখবে না। ক্ষমা.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ الْمُؤْمِنُ مَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ مِنْ الْعُقُوبَةِ مَا طَمِعَ بِجَنَّتِهِ أَحَدٌ وَلَوْ يَعْلَمُ الْكَافِرُ مَا عِنْدَ اللَّهِ مِنْ الرَّحْمَةِ مَا ‏ ‏قَنَطَ ‏ ‏مِنْ رَحْمَتِهِ أَحَدٌ ‏","","",""],[8800,8800,"","( পড়ুন, গীতসংহিতা ১১৯: ৯৭ - ১০০.)","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏صَفَرَ ‏ ‏وَلَا ‏ ‏هَامَةَ ‏ ‏وَلَا ‏ ‏نَوْءَ ‏","","",""]];
